window.QB_TKP_B21 = [
{"id":"TKP-3801","q":"Di meja loket pembayaran retribusi, Anda melihat stiker QRIS pembayaran digital tertempel menutupi QRIS resmi instansi. Seorang wajib pajak hendak memindainya untuk membayar. Tindakan paling tepat adalah ....","opts":[{"t":"Mencegah wajib pajak memindai, mengamankan stiker mencurigakan, dan melaporkannya ke atasan serta unit TI","s":5},{"t":"Menyarankan wajib pajak membayar tunai saja tanpa menindaklanjuti stiker tersebut","s":4},{"t":"Melepas stiker itu diam-diam lalu membuangnya","s":3},{"t":"Membiarkan karena mungkin stiker cadangan dari bank","s":2},{"t":"Ikut memindai untuk memastikan stiker itu berfungsi","s":1}],"ex":"QRIS palsu yang ditempel di atas QRIS resmi adalah modus quishing; cegah korban, amankan bukti, dan laporkan."},
{"id":"TKP-3802","q":"Anda menerima file Undangan Pernikahan.apk dari nomor tak dikenal melalui WhatsApp. Pesan itu meminta Anda memasang aplikasi untuk membuka undangan. Sikap paling tepat adalah ....","opts":[{"t":"Tidak memasang, menghapus pesan, memblokir pengirim, dan mengingatkan rekan agar waspada","s":5},{"t":"Tidak memasang dan menghapus pesan begitu saja","s":4},{"t":"Meneruskan ke rekan untuk memastikan apakah undangan itu asli","s":3},{"t":"Memasang di HP cadangan untuk melihat isinya","s":2},{"t":"Memasang aplikasi lalu membuka undangannya","s":1}],"ex":"File .apk dari WhatsApp adalah modus malware pencuri SMS OTP dan m-banking; jangan pernah dipasang."},
{"id":"TKP-3803","q":"SMS masuk: paket Anda tertahan, klik tautan pembayaran digital untuk bea Rp15.000. Anda memang menunggu paket, tetapi tidak pernah belanja dengan jasa itu. Tindakan paling tepat adalah ....","opts":[{"t":"Mengabaikan SMS, mengecek status paket lewat aplikasi resmi kurir, dan melaporkan SMS sebagai spam","s":5},{"t":"Mengabaikan SMS tersebut tanpa verifikasi","s":4},{"t":"Mengklik tautan sekadar untuk melihat tampilannya","s":3},{"t":"Meneruskan SMS ke keluarga agar mereka waspada","s":2},{"t":"Mengklik tautan dan membayar karena nominalnya kecil","s":1}],"ex":"SMS paket fiktif adalah phishing; verifikasi hanya lewat aplikasi atau situs resmi kurir."},
{"id":"TKP-3804","q":"Nomor baru di WhatsApp mengaku sebagai atasan Anda dan meminta dibelikan pulsa Rp500.000 segera karena sedang rapat penting. Gaya bahasanya mirip atasan Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menuruti, memverifikasi lewat nomor resmi atasan atau tatap muka, lalu melaporkan nomor penipu","s":5},{"t":"Menunda dan menunggu atasan menghubungi lewat nomor biasanya","s":4},{"t":"Membalas meminta bukti bahwa itu benar atasan","s":3},{"t":"Membelikan pulsa separuh dulu sebagai tanda percaya","s":2},{"t":"Langsung membelikan pulsa karena takut dianggap tidak sigap","s":1}],"ex":"Penipuan mengatasnamakan atasan marak terjadi; verifikasi identitas lewat kanal resmi sebelum bertindak."},
{"id":"TKP-3805","q":"Di Telegram, akun perusahaan menawarkan kerja paruh waktu via internet: like dan subscribe video digaji Rp50.000 per tugas, tetapi Anda diminta deposit Rp200.000 dulu sebagai jaminan. Sikap paling tepat adalah ....","opts":[{"t":"Menolak, tidak mentransfer, memblokir akun, dan melaporkan ke kanal aduan penipuan","s":5},{"t":"Menolak tawaran dan keluar dari grup tersebut","s":4},{"t":"Mencoba satu tugas kecil tanpa deposit untuk memastikan","s":3},{"t":"Bertanya ke rekan apakah ada yang pernah ikut dan berhasil","s":2},{"t":"Menyetor deposit karena imbalannya terlihat menggiurkan","s":1}],"ex":"Tugas berbayar yang meminta deposit di muka adalah penipuan; pekerjaan resmi tidak pernah meminta uang pelamar."},
{"id":"TKP-3806","q":"Beredar tautan pendaftaran bantuan sosial digital yang meminta NIK, nomor KK, dan kode OTP. Tetangga Anda yang lanjut usia meminta bantuan mengisinya. Tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan itu modus pencurian data, tidak mengisi apa pun, dan mengarahkan ke situs resmi pemerintah","s":5},{"t":"Menolak membantu mengisi dan menyarankan bertanya ke kelurahan","s":4},{"t":"Mengisi data seadanya agar tetangga tidak kecewa","s":3},{"t":"Mengisi dengan NIK tetangga karena kasihan","s":2},{"t":"Mengisi lengkap termasuk kode OTP demi mempercepat pencairan","s":1}],"ex":"Bansos resmi tidak pernah meminta kode OTP; data pribadi yang diserahkan ke tautan palsu disalahgunakan."},
{"id":"TKP-3807","q":"Di ruang tunggu publik tersedia WiFi gratis bernama KANTOR_GRATIS tanpa kata sandi. Anda perlu mengirim dokumen dinas via internet yang bersifat internal. Sikap paling tepat adalah ....","opts":[{"t":"Tidak memakai WiFi publik untuk urusan dinas; memakai data seluler atau VPN resmi instansi","s":5},{"t":"Memakai WiFi itu hanya untuk membuka berita, bukan dokumen dinas","s":4},{"t":"Memakai WiFi itu karena dokumen hanya bersifat internal","s":3},{"t":"Memakai WiFi itu setelah bertanya ke petugas sekitar","s":2},{"t":"Langsung mengirim dokumen lewat WiFi gratis tersebut","s":1}],"ex":"WiFi publik tanpa pengaman rawan disadap; data dinas hanya lewat jaringan aman atau VPN resmi."},
{"id":"TKP-3808","q":"Seseorang menelepon mengaku dari bank, menyebut nama lengkap Anda, lalu meminta kode OTP untuk verifikasi keamanan rekening digital Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak memberikan OTP, menutup telepon, dan menghubungi call center resmi bank untuk konfirmasi","s":5},{"t":"Menutup telepon tanpa memberikan apa pun","s":4},{"t":"Meminta penelepon mengirim surat resmi dulu","s":3},{"t":"Memberikan sebagian digit OTP untuk verifikasi","s":2},{"t":"Memberikan kode OTP karena ia tahu data pribadi Anda","s":1}],"ex":"Bank tidak pernah meminta OTP; penipu bisa memperoleh nama korban dari kebocoran data."},
{"id":"TKP-3809","q":"Anda menerima email berisi tautan reset kata sandi, padahal Anda tidak pernah memintanya. Email itu tampak dari aplikasi layanan yang Anda pakai. Tindakan paling tepat adalah ....","opts":[{"t":"Mengabaikan tautan, membuka aplikasi resmi secara manual, dan melaporkan email ke admin TI","s":5},{"t":"Menghapus email tersebut tanpa mengklik apa pun","s":4},{"t":"Mengklik tautan untuk memastikan apakah akun Anda bermasalah","s":3},{"t":"Meneruskan email ke rekan untuk dimintai pendapat","s":2},{"t":"Mengklik tautan dan mengganti kata sandi sesuai instruksi email","s":1}],"ex":"Email reset yang tidak diminta bisa jadi phishing atau tanda akun dibobol; akses layanan lewat jalur resmi."},
{"id":"TKP-3810","q":"Rekan menerima email phishing dari alamat mirip vendor resmi berisi invoice format .zip dan diminta segera membayar. Rekan bertanya pendapat Anda. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan tidak membuka lampiran, memverifikasi ke vendor lewat kontak resmi, dan melaporkan ke TI","s":5},{"t":"Menyarankan menunggu sampai ada konfirmasi tagihan resmi","s":4},{"t":"Menyarankan membuka lampiran di komputer lain yang tidak penting","s":3},{"t":"Menyarankan membayar sebagian dulu agar tidak terlambat","s":2},{"t":"Menyarankan segera membayar karena email terlihat meyakinkan","s":1}],"ex":"Lampiran .zip dari alamat mirip resmi adalah vektor malware dan penipuan invoice; verifikasi lewat kontak resmi."},
{"id":"TKP-3811","q":"Saat browsing internet, muncul pop-up: komputer Anda terinfeksi, segera hubungi nomor dukungan teknis yang tertera. Layar tampak terkunci oleh peringatan itu. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menghubungi nomor itu, menutup browser paksa, memindai perangkat, dan melapor ke unit TI","s":5},{"t":"Menutup tab browser dan melanjutkan pekerjaan","s":4},{"t":"Memotret layar lalu bertanya di grup WhatsApp","s":3},{"t":"Menghubungi nomor itu untuk memastikan","s":2},{"t":"Mengikuti instruksi pop-up dan memberikan akses remote","s":1}],"ex":"Pop-up dukungan teknis palsu bertujuan mengambil alih perangkat; dukungan resmi tidak pernah muncul lewat pop-up."},
{"id":"TKP-3812","q":"Di grup WhatsApp dinas, seseorang membagikan tautan pemendek dengan pesan cek SK kenaikan pangkat terbaru di sini. Pengirimnya nomor yang jarang aktif. Sikap paling tepat adalah ....","opts":[{"t":"Tidak mengklik, memverifikasi ke bagian kepegawaian lewat kanal resmi, dan mengingatkan anggota grup","s":5},{"t":"Tidak mengklik dan menunggu informasi resmi","s":4},{"t":"Mengklik karena penasaran dengan isi SK","s":3},{"t":"Meneruskan ke grup lain agar ikut mengecek","s":2},{"t":"Mengklik lalu mengisi data login yang diminta situs itu","s":1}],"ex":"Tautan pemendek di grup adalah teknik menyamarkan phishing; info kepegawaian hanya dari kanal resmi."},
{"id":"TKP-3813","q":"Akun media sosial mengatasnamakan instansi Anda, memakai logo resmi, dan menggalang sumbangan bencana via transfer pribadi. Warga mulai bertanya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengumumkan akun itu palsu di kanal resmi, melaporkan akun, dan berkoordinasi dengan humas","s":5},{"t":"Melaporkan akun palsu ke platform media sosial","s":4},{"t":"Mengabaikan karena bukan akun resmi instansi","s":3},{"t":"Menghubungi admin akun palsu untuk klarifikasi","s":2},{"t":"Ikut menyumbang karena tujuannya kemanusiaan","s":1}],"ex":"Akun kloningan instansi untuk donasi adalah penipuan; klarifikasi resmi melindungi warga dan reputasi instansi."},
{"id":"TKP-3814","q":"Anda menerima formulir survei kepuasan layanan digital yang meminta alamat email dinas beserta kata sandinya agar bisa login responden. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mengisi, tidak memberikan kata sandi, dan melaporkan formulir mencurigakan ke unit TI","s":5},{"t":"Mengisi survei tetapi mengosongkan kolom kata sandi","s":4},{"t":"Mengisi dengan kata sandi palsu agar bisa lanjut","s":3},{"t":"Bertanya ke rekan apakah mereka juga menerima survei itu","s":2},{"t":"Mengisi lengkap karena surveinya terlihat resmi","s":1}],"ex":"Survei resmi tidak pernah meminta kata sandi; itu phishing berkedok kuesioner."},
{"id":"TKP-3815","q":"Di area parkir kantor, stiker QR pembayaran parkir digital resmi tertutup stiker QR lain yang berbeda. Petugas parkir tidak ada di tempat. Sikap paling tepat adalah ....","opts":[{"t":"Tidak memindai QR asing, membayar tunai atau via aplikasi resmi, dan melaporkan ke pengelola parkir","s":5},{"t":"Membayar tunai saja tanpa mempedulikan stiker itu","s":4},{"t":"Melepas stiker asing lalu memindai QR aslinya","s":3},{"t":"Memindai QR yang paling atas karena terlihat baru","s":2},{"t":"Memindai QR asing itu untuk mencoba","s":1}],"ex":"Penimpaan QR pembayaran adalah quishing; gunakan kanal pembayaran resmi dan laporkan temuan."},
{"id":"TKP-3816","q":"Pesan WhatsApp mengabarkan Anda memenangkan undian berhadiah mobil dari operator seluler dan diminta membayar pajak hadiah Rp1.000.000 dulu. Tindakan paling tepat adalah ....","opts":[{"t":"Mengabaikan, memblokir pengirim, dan melaporkan sebagai penipuan","s":5},{"t":"Menghapus pesan tanpa menanggapi","s":4},{"t":"Mengecek ke situs operator lewat pencarian umum","s":3},{"t":"Membalas menanyakan syarat pengambilan hadiah","s":2},{"t":"Mentransfer pajak hadiah agar mobil segera dikirim","s":1}],"ex":"Undian yang meminta biaya di muka adalah penipuan klasik; pemenang resmi tidak dipungut biaya."},
{"id":"TKP-3817","q":"Seseorang menghubungi Anda mengaku salah transfer digital Rp2.000.000 ke rekening Anda dan memohon dikembalikan segera ke nomor rekening berbeda. Anda belum mengecek mutasi. Tindakan paling tepat adalah ....","opts":[{"t":"Mengecek mutasi resmi bank dulu; jika benar salah transfer, kembalikan ke rekening pengirim asal","s":5},{"t":"Menunggu sampai ada bukti transfer yang jelas","s":4},{"t":"Mengembalikan ke rekening yang ia sebutkan karena kasihan","s":3},{"t":"Mengembalikan separuh dulu sebagai itikad baik","s":2},{"t":"Langsung mentransfer ke rekening yang diminta","s":1}],"ex":"Modus salah transfer palsu memanfaatkan kepanikan; pengembalian hanya ke rekening asal setelah verifikasi mutasi."},
{"id":"TKP-3818","q":"Undangan kalender digital masuk ke email dinas: Rapat Koordinasi Nasional dengan tautan video conference, tetapi Anda tidak mengenal penyelenggaranya. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mengklik tautan, memverifikasi agenda ke atasan, dan melaporkan undangan asing ke TI","s":5},{"t":"Mengabaikan undangan tersebut","s":4},{"t":"Mengklik tautan untuk melihat siapa pesertanya","s":3},{"t":"Meneruskan undangan ke rekan yang mungkin diundang","s":2},{"t":"Mengikuti tautan dan mengisi data kehadiran yang diminta","s":1}],"ex":"Undangan kalender berisi tautan adalah celah phishing; agenda dinas resmi selalu terkonfirmasi lewat atasan."},
{"id":"TKP-3819","q":"Seseorang menelepon mengaku staf IT kantor pusat dan meminta akses remote via internet ke komputer Anda untuk instalasi pembaruan keamanan. Ia tahu nama unit kerja Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak, memverifikasi identitasnya lewat helpdesk resmi, dan mengikuti prosedur TI yang berlaku","s":5},{"t":"Meminta ia mengirim email resmi dulu sebelum memberi akses","s":4},{"t":"Memberi akses sambil mengawasi layarnya","s":3},{"t":"Memberi akses karena ia tahu detail unit kerja","s":2},{"t":"Langsung memberi akses remote agar pembaruan cepat selesai","s":1}],"ex":"IT resmi tidak meminta akses dadakan via telepon; verifikasi lewat helpdesk resmi mencegah pembajakan perangkat."},
{"id":"TKP-3820","q":"Rekan mengaku baru saja mengklik tautan phishing dan memasukkan email serta kata sandi dinasnya. Ia panik dan meminta saran Anda. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan segera mengganti kata sandi dari perangkat aman, mengaktifkan verifikasi dua langkah, dan melapor ke TI","s":5},{"t":"Menyarankan mengganti kata sandi secepatnya","s":4},{"t":"Menyarankan menunggu dan melihat apakah ada yang aneh","s":3},{"t":"Menyarankan menghapus riwayat browser saja","s":2},{"t":"Menyarankan tidak usah khawatir karena tautannya sudah ditutup","s":1}],"ex":"Kredensial yang bocor harus segera diganti dari perangkat aman disertai 2FA dan pelaporan insiden ke TI."},
{"id":"TKP-3821","q":"Anda menemukan flashdisk berisi data digital tergeletak di parkir kantor berlabel Daftar Gaji Karyawan 2026. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mencolokkannya ke komputer mana pun dan menyerahkannya ke unit TI atau keamanan","s":5},{"t":"Menyerahkannya ke bagian umum tanpa mencolokkan","s":4},{"t":"Mencolokkan ke komputer pribadi untuk melihat isinya","s":3},{"t":"Mengumumkannya di grup agar pemiliknya mengambil","s":2},{"t":"Mencolokkan ke komputer kantor untuk mencari tahu pemiliknya","s":1}],"ex":"Perangkat USB asing adalah umpan malware; jangan pernah dicolokkan, serahkan ke pihak berwenang."},
{"id":"TKP-3822","q":"Beredar lowongan CPNS jalur khusus di media sosial yang meminta biaya pendaftaran Rp350.000 via transfer ke rekening pribadi agar lolos seleksi administrasi. Sikap paling tepat adalah ....","opts":[{"t":"Menyatakan itu penipuan, tidak mendaftar, dan melaporkan akun ke kanal resmi serta mengingatkan pelamar lain","s":5},{"t":"Mengabaikan lowongan tersebut","s":4},{"t":"Mendaftar tetapi tidak membayar biayanya","s":3},{"t":"Bertanya ke rekan apakah lowongan itu benar","s":2},{"t":"Mendaftar dan membayar agar tidak ketinggalan kesempatan","s":1}],"ex":"Rekrutmen ASN resmi gratis dan hanya lewat portal resmi; pungutan biaya adalah penipuan."},
{"id":"TKP-3823","q":"Anda menemukan situs layanan pengaduan digital yang tampilannya mirip situs resmi instansi, tetapi alamatnya berbeda satu huruf. Warga sudah banyak mengisinya. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan situs tiruan ke unit TI dan humas, serta mengimbau warga memakai alamat resmi yang benar","s":5},{"t":"Menggunakan situs resmi yang sudah Anda kenal saja","s":4},{"t":"Mencoba mengisi situs tiruan untuk memastikan","s":3},{"t":"Membiarkan karena tampilannya meyakinkan","s":2},{"t":"Ikut mengisi karena kebetulan ingin melapor","s":1}],"ex":"Typosquatting meniru situs resmi untuk mencuri data; selalu akses layanan lewat alamat resmi atau bookmark."},
{"id":"TKP-3824","q":"Kurir menghubungi Anda via WhatsApp: ada paket COD Rp450.000 atas nama Anda, diminta transfer dulu sebelum paket dikirim karena kurir jauh. Anda tidak memesan apa pun. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak, tidak mentransfer, dan memblokir kontak tersebut","s":5},{"t":"Menolak paket itu dengan sopan","s":4},{"t":"Meminta foto paket dulu sebelum memutuskan","s":3},{"t":"Mentransfer setengah sebagai tanda jadi","s":2},{"t":"Mentransfer karena khawatir paket penting","s":1}],"ex":"COD fiktif menekan korban agar transfer dulu; tolak dan verifikasi bila memang ada pesanan."},
{"id":"TKP-3825","q":"Seseorang melakukan panggilan video via aplikasi mengaku petugas bank dan meminta Anda menunjukkan KTP serta menyebut kode verifikasi. Wajahnya tampak sedikit tidak wajar. Tindakan paling tepat adalah ....","opts":[{"t":"Mengakhiri panggilan, tidak memberikan data, dan mengonfirmasi lewat call center resmi bank","s":5},{"t":"Mengakhiri panggilan tanpa memberikan apa pun","s":4},{"t":"Meminta ia menunjukkan kartu identitasnya dulu","s":3},{"t":"Menunjukkan KTP tetapi tidak menyebut kode","s":2},{"t":"Menuruti semua permintaannya karena terlihat seperti petugas","s":1}],"ex":"Wajah tidak wajar mengindikasikan deepfake; bank tidak meminta data sensitif lewat panggilan video dadakan."},
{"id":"TKP-3826","q":"Di media sosial viral video wali kota mengumumkan lockdown total mulai besok. Video itu belum ada di akun resmi pemda dan gerakannya terlihat janggal. Sebagai ASN, tindakan paling tepat adalah ....","opts":[{"t":"Tidak menyebarkan, memverifikasi ke humas pemda, dan mengimbau warga menunggu pengumuman resmi","s":5},{"t":"Tidak menyebarkan dan menunggu klarifikasi resmi","s":4},{"t":"Menyimpan video untuk ditonton nanti","s":3},{"t":"Meneruskan ke grup keluarga agar waspada","s":2},{"t":"Ikut menyebarkan karena videonya meyakinkan","s":1}],"ex":"Video viral tanpa sumber resmi yang gerakannya janggal patut diduga deepfake; verifikasi ke humas sebelum bereaksi."},
{"id":"TKP-3827","q":"Anda menerima voice note WhatsApp bersuara mirip sekretaris daerah meminta transfer dana operasional ke rekening pribadi karena mendesak. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mentransfer, mengonfirmasi langsung lewat nomor resmi atau tatap muka, dan melaporkan nomor tersebut","s":5},{"t":"Mengabaikan pesan dan menunggu konfirmasi resmi","s":4},{"t":"Membalas meminta surat perintah tertulis","s":3},{"t":"Mentransfer sebagian dulu sambil menunggu konfirmasi","s":2},{"t":"Langsung mentransfer karena suaranya persis","s":1}],"ex":"Kloning suara AI kini mampu meniru pejabat; perintah dana hanya sah lewat prosedur dan kanal resmi."},
{"id":"TKP-3828","q":"Beredar foto banjir bandang dahsyat yang diklaim terjadi di kabupaten Anda. Foto itu dibuat dengan aplikasi kecerdasan buatan dan memicu kepanikan warga. Tindakan paling tepat adalah ....","opts":[{"t":"Merujuk warga ke informasi resmi BPBD, tidak menyebarkan foto, dan melaporkan konten menyesatkan","s":5},{"t":"Tidak menyebarkan dan mengecek ke situs resmi","s":4},{"t":"Meneruskan ke grup dengan catatan belum terverifikasi","s":3},{"t":"Mengunggah ulang dengan tanda tanya","s":2},{"t":"Ikut menyebarkan agar warga waspada","s":1}],"ex":"Foto AI hoaks bencana menimbulkan kepanikan; rujukan informasi bencana hanya dari BPBD dan kanal resmi."},
{"id":"TKP-3829","q":"Video kerusuhan yang terjadi tiga tahun lalu viral kembali di media sosial dengan narasi terjadi kemarin di kota Anda. Banyak warga resah. Tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan video itu peristiwa lama, menunjukkan sumber aslinya, dan mengimbau tidak menyebarkan ulang","s":5},{"t":"Tidak ikut menyebarkan dan mengecek tanggal video","s":4},{"t":"Menyimpan video sebagai arsip pribadi","s":3},{"t":"Meneruskan dengan keterangan butuh klarifikasi","s":2},{"t":"Ikut menyebarkan agar aparat bertindak","s":1}],"ex":"Konten lama yang diklaim baru adalah manipulasi konteks; cek tanggal dan sumber sebelum bereaksi."},
{"id":"TKP-3830","q":"Beredar tangkapan layar percakapan WhatsApp yang diklaim sebagai chat pribadi pejabat membocorkan isi SK mutasi. Format tulisannya tidak konsisten. Tindakan paling tepat adalah ....","opts":[{"t":"Menganggapnya belum terverifikasi, tidak menyebarkan, dan menunggu pengumuman resmi kepegawaian","s":5},{"t":"Mengabaikan tangkapan layar tersebut","s":4},{"t":"Meneruskan ke rekan dekat saja","s":3},{"t":"Mengunggah ke media sosial menuntut klarifikasi","s":2},{"t":"Menyebarkan sebagai bukti kebocoran","s":1}],"ex":"Tangkapan layar mudah dipalsukan; isu mutasi hanya sah dari pengumuman resmi kepegawaian."},
{"id":"TKP-3831","q":"Rekan hendak mengunggah video ke media sosial yang diklaim sebagai bukti pungli di unit Anda, tetapi keaslian video belum terverifikasi. Saran paling tepat adalah ....","opts":[{"t":"Mencegah pengunggahan, menyarankan verifikasi dan pelaporan lewat kanal resmi pengawasan","s":5},{"t":"Menyarankan menunggu sampai ada bukti tambahan","s":4},{"t":"Membiarkan karena itu hak rekan","s":3},{"t":"Menyarankan mengunggah dengan sensor wajah","s":2},{"t":"Mendukung pengunggahan agar cepat viral","s":1}],"ex":"Tuduhan tanpa verifikasi merugikan banyak pihak; dugaan pelanggaran dilapor lewat kanal pengawasan resmi."},
{"id":"TKP-3832","q":"Saat panggilan video via aplikasi, wajah penelepon yang mengaku kerabat Anda tampak tidak sinkron dengan suaranya, lalu ia meminta transfer uang darurat. Tindakan paling tepat adalah ....","opts":[{"t":"Mengakhiri panggilan, menghubungi kerabat lewat nomor aslinya, dan melaporkan upaya penipuan","s":5},{"t":"Mengakhiri panggilan tanpa menuruti permintaan","s":4},{"t":"Melanjutkan panggilan sambil merekam","s":3},{"t":"Mentransfer sedikit karena kasihan","s":2},{"t":"Mentransfer sesuai permintaan","s":1}],"ex":"Ketidaksinkronan wajah-suara menandakan deepfake real-time; verifikasi lewat kontak asli sebelum bertindak."},
{"id":"TKP-3833","q":"Konten digital buatan AI yang menggambarkan rapat dinas Anda beredar dan diklaim sebagai dokumentasi asli, padahal rapat itu tidak pernah terjadi. Tindakan paling tepat adalah ....","opts":[{"t":"Berkoordinasi dengan humas untuk klarifikasi resmi dan melaporkan konten palsu ke platform","s":5},{"t":"Melaporkan konten palsu ke platform media sosial","s":4},{"t":"Mengabaikan karena jelas rekayasa","s":3},{"t":"Mengomentari di kolom komentar bahwa itu palsu","s":2},{"t":"Membiarkan karena tidak merugikan langsung","s":1}],"ex":"Dokumentasi palsu kegiatan dinas merusak kepercayaan publik; klarifikasi resmi dan pelaporan konten wajib dilakukan."},
{"id":"TKP-3834","q":"Seorang warga datang ke layanan Anda membawa video dari internet sebagai bukti sengketa tanah, tetapi video itu tampak hasil rekayasa digital. Sikap paling tepat adalah ....","opts":[{"t":"Menjelaskan bukti sah mengikuti prosedur hukum, mengarahkan ke dokumen resmi, tanpa menghakimi warga","s":5},{"t":"Menolak video itu dan meminta dokumen tertulis","s":4},{"t":"Menerima video sebagai bahan pertimbangan","s":3},{"t":"Menyarankan warga mengunggah video agar viral","s":2},{"t":"Memproses sengketa berdasarkan video tersebut","s":1}],"ex":"Video internet bukan alat bukti formal; layani warga dengan mengarahkan ke dokumen dan prosedur resmi."},
{"id":"TKP-3835","q":"Beredar video digital pidato presiden dengan sulih suara yang mengubah maknanya, diklaim sebagai pernyataan terbaru. Tindakan paling tepat adalah ....","opts":[{"t":"Mengecek pidato asli di kanal resmi kepresidenan, tidak menyebarkan versi sulih suara","s":5},{"t":"Tidak menyebarkan sebelum ada klarifikasi","s":4},{"t":"Meneruskan dengan catatan meragukan","s":3},{"t":"Mengomentari bahwa sulih suaranya aneh","s":2},{"t":"Menyebarkan karena isinya penting","s":1}],"ex":"Dubbing palsu memelintir pernyataan resmi; pidato otentik hanya dari kanal resmi kepresidenan."},
{"id":"TKP-3836","q":"Foto digital pejabat instansi Anda hasil editan beredar di internet, menampilkannya di acara yang tidak pernah ia hadiri disertai narasi negatif. Tindakan paling tepat adalah ....","opts":[{"t":"Berkoordinasi dengan humas untuk klarifikasi dan melaporkan konten manipulatif","s":5},{"t":"Melaporkan konten itu ke platform","s":4},{"t":"Mengabaikan karena foto editan biasa","s":3},{"t":"Meneruskan ke rekan untuk ditertawakan","s":2},{"t":"Ikut menyebarkan narasinya","s":1}],"ex":"Foto editan bernarasi negatif adalah pencemaran nama; klarifikasi resmi melindungi institusi dan individu."},
{"id":"TKP-3837","q":"Humas meminta Anda membantu menyiapkan klarifikasi atas hoaks deepfake yang menyerang instansi. Langkah paling tepat adalah ....","opts":[{"t":"Menyiapkan pernyataan singkat berbasis fakta, menyertakan bukti pembanding, dan merilis lewat kanal resmi","s":5},{"t":"Merilis pernyataan singkat lewat kanal resmi","s":4},{"t":"Membalas satu per satu komentar penyebar hoaks","s":3},{"t":"Menunggu hoaks mereda sendiri","s":2},{"t":"Membalas hoaks dengan hoaks tandingan","s":1}],"ex":"Klarifikasi efektif: cepat, berbasis fakta, lewat kanal resmi, tanpa terpancing emosi."},
{"id":"TKP-3838","q":"Grup WhatsApp keluarga ramai membagikan video hoaks kesehatan yang dibuat dengan AI. Anda sebagai anggota keluarga yang ASN, tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan dengan santun cara mengecek fakta dan merujuk ke sumber kesehatan resmi","s":5},{"t":"Mengingatkan agar tidak mudah percaya video viral","s":4},{"t":"Keluar dari grup agar tidak terpapar","s":3},{"t":"Mendiamkan karena segan menasihati orang tua","s":2},{"t":"Ikut membagikan karena pesannya baik","s":1}],"ex":"Edukasi literasi digital dimulai dari lingkaran terdekat dengan cara santun dan rujukan resmi."},
{"id":"TKP-3839","q":"Rekan menggunakan aplikasi penukar wajah untuk membuat lelucon video atasan dan hendak mengunggahnya ke media sosial. Saran paling tepat adalah ....","opts":[{"t":"Mencegah pengunggahan dan mengingatkan risiko hukum serta etik bagi ASN","s":5},{"t":"Menyarankan tidak mengunggah ke media sosial","s":4},{"t":"Membiarkan karena hanya lelucon internal","s":3},{"t":"Meminta dikirimi videonya untuk koleksi","s":2},{"t":"Ikut membantu menyebarkan leluconnya","s":1}],"ex":"Face-swap figur atasan melanggar etik ASN dan bisa dijerat hukum; cegah sebelum terunggah."},
{"id":"TKP-3840","q":"Beredar video testimoni obat di media sosial yang memakai wajah dokter terkenal hasil rekayasa AI. Banyak warga tertipu dan membeli. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan konten ke platform dan mengimbau warga membeli obat lewat jalur resmi kesehatan","s":5},{"t":"Mengimbau warga tidak mudah percaya testimoni","s":4},{"t":"Mengabaikan karena bukan kewenangan Anda","s":3},{"t":"Meneruskan video dengan peringatan","s":2},{"t":"Ikut membagikan karena obatnya mungkin manjur","s":1}],"ex":"Testimoni AI adalah penipuan kesehatan; laporkan konten dan arahkan warga ke layanan kesehatan resmi."},
{"id":"TKP-3841","q":"Video kecelakaan kerja yang dimanipulasi digital dipakai pihak tertentu untuk menuntut ganti rugi ke instansi Anda. Sikap paling tepat adalah ....","opts":[{"t":"Menyerahkan penanganan ke prosedur hukum dengan bukti otentik, tanpa terprovokasi opini","s":5},{"t":"Meminta tim hukum memverifikasi keaslian video","s":4},{"t":"Menegosiasi damai agar tidak viral","s":3},{"t":"Membayar tuntutan agar masalah selesai","s":2},{"t":"Menyerang balik dengan menyebar video tandingan","s":1}],"ex":"Tuntutan berbasis bukti manipulatif diselesaikan lewat prosedur hukum dengan bukti otentik."},
{"id":"TKP-3842","q":"Anda menerima telepon via internet dengan suara mirip anak Anda menangis mengaku kecelakaan dan butuh transfer segera. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak panik, menghubungi anak lewat nomor aslinya, dan tidak mentransfer sebelum terkonfirmasi","s":5},{"t":"Menutup telepon dan mengecek kabar anak","s":4},{"t":"Mentransfer sedikit sambil menunggu kabar","s":3},{"t":"Meminta penelepon mengirim foto","s":2},{"t":"Langsung mentransfer karena panik","s":1}],"ex":"Penipuan suara AI memanfaatkan kepanikan orang tua; konfirmasi lewat kontak asli adalah kunci."},
{"id":"TKP-3843","q":"Gambar hasil AI yang beredar di internet dan diklaim sebagai foto udara proyek diklaim menunjukkan proyek mangkrak, padahal proyek berjalan normal. Tindakan paling tepat adalah ....","opts":[{"t":"Menunjukkan dokumentasi progres resmi dan mengajak verifikasi lapangan","s":5},{"t":"Merilis foto progres asli lewat kanal resmi","s":4},{"t":"Mengabaikan karena proyek memang berjalan","s":3},{"t":"Berdebat di kolom komentar","s":2},{"t":"Menghapus komentar kritis","s":1}],"ex":"Tudingan berbasis gambar AI dilawan dengan dokumentasi resmi dan keterbukaan verifikasi lapangan."},
{"id":"TKP-3844","q":"Meme satir pejabat beredar luas di media sosial dan sebagian warga menganggapnya fakta. Sebagai ASN, sikap paling tepat adalah ....","opts":[{"t":"Membedakan satir dan fakta saat ada yang bertanya, merujuk ke informasi resmi tanpa memberangus kritik","s":5},{"t":"Menjelaskan itu hanya meme bila ada yang bertanya","s":4},{"t":"Ikut menyebarkan karena lucu","s":3},{"t":"Melaporkan semua meme sebagai hoaks","s":2},{"t":"Menuntut pembuat meme","s":1}],"ex":"Satir bukan hoaks; ASN meluruskan fakta dengan rujukan resmi tanpa anti-kritik."},
{"id":"TKP-3845","q":"Anda ragu atas keaslian sebuah video viral di internet terkait kebijakan pemerintah. Langkah verifikasi paling tepat adalah ....","opts":[{"t":"Menelusuri sumber asli, memakai pencarian gambar terbalik, dan mengecek kanal resmi sebelum menyimpulkan","s":5},{"t":"Menunggu klarifikasi resmi tanpa menyebarkan","s":4},{"t":"Bertanya ke grup WhatsApp","s":3},{"t":"Mempercayai karena banyak yang membagikan","s":2},{"t":"Langsung menyebarkan dengan narasi sendiri","s":1}],"ex":"Verifikasi berlapis: sumber asli, pencarian gambar terbalik, dan kanal resmi."},
{"id":"TKP-3846","q":"Pelaku diduga memakai video deepfake untuk lolos verifikasi wajah di aplikasi layanan Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan temuan ke unit TI dan pengembang aplikasi untuk penguatan sistem verifikasi","s":5},{"t":"Menolak verifikasi yang mencurigakan itu","s":4},{"t":"Meloloskan karena sistem menerimanya","s":3},{"t":"Membiarkan karena di luar tugas Anda","s":2},{"t":"Memberi tahu pelaku cara yang benar","s":1}],"ex":"Celah verifikasi wajah harus dilaporkan untuk penguatan sistem, bukan dimanfaatkan atau diabaikan."},
{"id":"TKP-3847","q":"Beredar pesan berantai aplikasi pesan instan: akan terjadi gempa besar malam ini menurut ramalan AI. Warga panik. Tindakan paling tepat adalah ....","opts":[{"t":"Merujuk ke informasi resmi BMKG, menjelaskan gempa tak bisa diramal, dan mengimbau tidak menyebar pesan","s":5},{"t":"Menjelaskan gempa tidak bisa diramal","s":4},{"t":"Meneruskan dengan catatan belum tentu benar","s":3},{"t":"Ikut bersiap mengungsi","s":2},{"t":"Menyebarkan agar warga waspada","s":1}],"ex":"Gempa tidak dapat diramal; rujukan kebencanaan hanya dari BMKG dan BPBD."},
{"id":"TKP-3848","q":"Iklan lowongan kerja di media sosial memakai wajah pejabat daerah hasil rekayasa AI dan meminta pelamar membayar biaya administrasi. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan iklan penipuan dan mengimbau pelamar mengecek portal lowongan resmi","s":5},{"t":"Mengimbau pelamar tidak membayar biaya apa pun","s":4},{"t":"Mengabaikan karena bukan instansi Anda","s":3},{"t":"Meneruskan iklan dengan peringatan","s":2},{"t":"Mendaftar untuk membuktikan","s":1}],"ex":"Lowongan resmi tidak memungut biaya dan tidak memakai wajah pejabat hasil rekayasa."},
{"id":"TKP-3849","q":"Anda diminta menyusun materi literasi digital tentang deteksi deepfake untuk sosialisasi ke masyarakat. Pendekatan paling tepat adalah ....","opts":[{"t":"Menyusun materi praktis: ciri deepfake, langkah verifikasi, dan daftar kanal cek fakta resmi","s":5},{"t":"Menyusun materi pengenalan deepfake secara umum","s":4},{"t":"Menayangkan contoh video deepfake tanpa penjelasan","s":3},{"t":"Menakut-nakuti peserta agar tidak pakai internet","s":2},{"t":"Menolak karena merasa bukan ahli","s":1}],"ex":"Literasi efektif memberi keterampilan verifikasi praktis, bukan sekadar menakut-nakuti."},
{"id":"TKP-3850","q":"Unit Anda mengusulkan SOP: setiap konten media sosial resmi wajib diverifikasi keasliannya sebelum diunggah. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan membantu menyusun SOP verifikasi konten yang jelas dan mudah dijalankan","s":5},{"t":"Mendukung usulan SOP tersebut","s":4},{"t":"Netral karena menambah beban kerja","s":3},{"t":"Menolak karena memperlambat publikasi","s":2},{"t":"Mengabaikan usulan itu","s":1}],"ex":"SOP verifikasi konten mencegah instansi ikut menyebar hoaks dan menjaga kredibilitas."},
{"id":"TKP-3851","q":"Anda melihat layar komputer rekan menampilkan situs judi online di internet saat jam kerja. Rekan meminta Anda merahasiakannya. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur rekan secara privat, memintanya berhenti, dan melaporkannya bila terus berlanjut","s":5},{"t":"Menegur rekan agar tidak mengulangi di jam kerja","s":4},{"t":"Mendiamkan karena urusan pribadi rekan","s":3},{"t":"Merahasiakan seperti yang diminta","s":2},{"t":"Ikut mencoba karena penasaran","s":1}],"ex":"Judi online di jam kerja melanggar disiplin dan hukum; tegur privat dulu, laporkan bila berulang."},
{"id":"TKP-3852","q":"Seseorang menawarkan rekan Anda pekerjaan sampingan sebagai admin situs judi online di internet dengan gaji besar, dikerjakan dari rumah. Rekan tergiur dan meminta pendapat Anda. Saran paling tepat adalah ....","opts":[{"t":"Menjelaskan itu tindak pidana, menyarankan menolak, dan melaporkan penawaran ke aparat","s":5},{"t":"Menyarankan rekan menolak tawaran itu","s":4},{"t":"Menyarankan rekan pikir-pikir dulu","s":3},{"t":"Membiarkan karena keputusan rekan","s":2},{"t":"Menyarankan rekan menerima karena gajinya besar","s":1}],"ex":"Menjadi admin judol adalah tindak pidana; tolak dan laporkan penawaran tersebut."},
{"id":"TKP-3853","q":"Rekan mengaku terlilit utang akibat judi online di internet dan memohon pinjaman uang kepada Anda untuk menutupinya. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak meminjami untuk judol, menyarankan konseling dan bantuan profesional pemulihan kecanduan","s":5},{"t":"Menolak meminjami dengan halus","s":4},{"t":"Meminjami sedikit karena kasihan","s":3},{"t":"Meminjami dengan syarat berhenti main","s":2},{"t":"Meminjami penuh agar rekan tenang","s":1}],"ex":"Mendanai pecandu judol memperparah masalah; arahkan ke konseling dan pemulihan profesional."},
{"id":"TKP-3854","q":"Penagih pinjaman online menelepon ke nomor kantor mencari rekan Anda yang menunggak di aplikasi pinjol, dengan nada mengancam. Tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan penagihan ke kantor tidak pantas, tidak memberikan data rekan, dan menyarankan lapor ke OJK","s":5},{"t":"Menyampaikan pesan singkat ke rekan tanpa detail","s":4},{"t":"Memberikan nomor pribadi rekan agar urusan cepat selesai","s":3},{"t":"Membiarkan penelepon berbicara dengan rekan","s":2},{"t":"Membantu menagih rekan agar kantor tidak terganggu","s":1}],"ex":"Penagih pinjol tak boleh meneror ke kantor; lindungi data rekan dan arahkan laporan ke OJK."},
{"id":"TKP-3855","q":"Foto KTP rekan disebar penagih pinjol ilegal ke grup WhatsApp disertai ancaman. Rekan malu dan ingin mengundurkan diri. Tindakan paling tepat adalah ....","opts":[{"t":"Menenangkan rekan, membantunya melaporkan ke polisi dan OJK, serta mengingatkan itu perbuatan melawan hukum","s":5},{"t":"Menyarankan rekan melapor ke polisi","s":4},{"t":"Menyarankan rekan membayar agar penyebaran berhenti","s":3},{"t":"Menyarankan rekan menghilang dari media sosial","s":2},{"t":"Ikut menyebarkan agar penagih jera","s":1}],"ex":"Penyebaran data pribadi oleh pinjol ilegal adalah pidana; korban harus melapor, bukan membayar atau menyerah."},
{"id":"TKP-3856","q":"Iklan judi online muncul berulang di komputer kantor saat Anda membuka situs berita di internet. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mengklik, menutup iklan, dan melaporkan ke unit TI untuk pemblokiran","s":5},{"t":"Menutup iklan dan melanjutkan browsing","s":4},{"t":"Mengklik untuk melihat situsnya","s":3},{"t":"Membiarkan karena hanya iklan","s":2},{"t":"Mengklik dan mendaftar karena penasaran","s":1}],"ex":"Iklan judol di perangkat dinas dilaporkan ke TI untuk diblokir; jangan pernah diklik."},
{"id":"TKP-3857","q":"Anda mengetahui rekan memakai jaringan internet kantor untuk bermain judi online di malam hari. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur dan melaporkan penyalahgunaan fasilitas kantor ke atasan atau unit TI","s":5},{"t":"Menegur rekan agar berhenti","s":4},{"t":"Mendiamkan karena di luar jam kerja","s":3},{"t":"Meminta rekan berbagi kemenangan","s":2},{"t":"Ikut bermain memakai jaringan kantor","s":1}],"ex":"Fasilitas internet kantor untuk judol adalah penyalahgunaan aset negara dan tindak pidana."},
{"id":"TKP-3858","q":"Seorang bandar judi online di internet menawarkan bantuan modal usaha kepada pegawai dengan syarat mempromosikan situsnya. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak tegas dan melaporkan tawaran ke aparat penegak hukum","s":5},{"t":"Menolak tawaran tersebut","s":4},{"t":"Meminta waktu berpikir","s":3},{"t":"Menerima modal tetapi tidak promosi","s":2},{"t":"Menerima dan ikut mempromosikan","s":1}],"ex":"Iming-iming bandar judol adalah jerat pidana; tolak dan laporkan."},
{"id":"TKP-3859","q":"Anak rekan Anda kecanduan game online di internet berunsur judi hingga mencuri uang. Rekan meminta saran. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan konseling profesional, membatasi akses, dan mengawasi dengan pendekatan kasih sayang","s":5},{"t":"Menyarankan membatasi gadget anak","s":4},{"t":"Menyarankan menghukum anak dengan keras","s":3},{"t":"Menyarankan membiarkan sampai bosan sendiri","s":2},{"t":"Menyarankan memberi uang agar tidak mencuri","s":1}],"ex":"Kecanduan game judi pada anak ditangani dengan konseling profesional dan pendampingan, bukan hukuman keras."},
{"id":"TKP-3860","q":"Situs judi online sudah diblokir, tetapi rekan memakai aplikasi VPN untuk tetap mengaksesnya dari HP kantor. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan itu tetap melanggar hukum dan melaporkan bila tidak berhenti","s":5},{"t":"Mengingatkan rekan agar berhenti","s":4},{"t":"Mendiamkan karena urusan pribadi","s":3},{"t":"Meminta diajari cara pakai VPN","s":2},{"t":"Ikut memakai VPN untuk mengakses","s":1}],"ex":"Mengakali pemblokiran dengan VPN tidak menghapus sifat pidananya."},
{"id":"TKP-3861","q":"Tawaran investasi via aplikasi menjanjikan keuntungan pasti 20% per bulan dan meminta Anda merekrut anggota baru. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak, tidak menyetor dana, dan melaporkan dugaan investasi bodong ke OJK","s":5},{"t":"Menolak tawaran tersebut","s":4},{"t":"Menyetor kecil untuk mencoba","s":3},{"t":"Bertanya ke rekan yang sudah ikut","s":2},{"t":"Menyetor dan merekrut anggota","s":1}],"ex":"Imbal hasil pasti plus rekrutmen adalah ciri skema ponzi; laporkan ke OJK."},
{"id":"TKP-3862","q":"Anda mendapati rekan menjual data warga dari aplikasi layanan kepada pihak judi online. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan pelanggaran berat itu ke atasan dan aparat penegak hukum","s":5},{"t":"Menegur keras rekan tersebut","s":4},{"t":"Meminta bagian keuntungan agar diam","s":3},{"t":"Mendiamkan karena takut bermusuhan","s":2},{"t":"Ikut membantu menjual data","s":1}],"ex":"Menjual data pribadi warga adalah pelanggaran berat dan pidana; wajib dilaporkan."},
{"id":"TKP-3863","q":"Notifikasi aplikasi judi online muncul di HP rekan saat rapat dinas berlangsung. Sikap paling tepat adalah ....","opts":[{"t":"Menegur rekan secara privat setelah rapat dan mengingatkannya tentang citra ASN","s":5},{"t":"Mengabaikan saat rapat, menegur setelahnya","s":4},{"t":"Menertawakan bersama rekan lain","s":3},{"t":"Membiarkan karena urusan pribadi","s":2},{"t":"Meminta link aplikasinya","s":1}],"ex":"Tegur privat menjaga martabat rekan sekaligus menegaskan judol tak pantas bagi ASN."},
{"id":"TKP-3864","q":"Seorang pegawai mempromosikan situs judi online di status WhatsApp-nya. Anda melihatnya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkannya bahwa promosi judol melanggar hukum dan etik ASN, serta melaporkannya","s":5},{"t":"Mengingatkannya untuk menghapus status itu","s":4},{"t":"Mengabaikan status tersebut","s":3},{"t":"Ikut membagikan statusnya","s":2},{"t":"Mendaftar lewat link yang dibagikan","s":1}],"ex":"Mempromosikan judol adalah tindak pidana; ASN wajib menjaga perilaku di ruang digital."},
{"id":"TKP-3865","q":"Aplikasi pinjaman online ilegal yang pernah dipakai warga meminta akses ke seluruh kontak HP dan mengancam menyebar data. Warga meminta bantuan Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menyarankan tidak memberi akses, menghapus aplikasi, dan melaporkan ke OJK serta polisi","s":5},{"t":"Menyarankan menghapus aplikasi itu","s":4},{"t":"Menyarankan membayar agar aman","s":3},{"t":"Menyarankan memberi akses kontak","s":2},{"t":"Menyarankan meminjam lagi untuk menutup","s":1}],"ex":"Pinjol ilegal tak berizin OJK; jangan beri akses data, hapus aplikasi, dan laporkan."},
{"id":"TKP-3866","q":"Rekan gali lubang tutup lubang dengan banyak aplikasi pinjol hingga gajinya habis untuk cicilan. Ia meminta saran. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan konseling keuangan, menyusun anggaran, dan berhenti berutang baru","s":5},{"t":"Menyarankan berhenti meminjam lagi","s":4},{"t":"Menyarankan meminjam ke koperasi untuk menutup","s":3},{"t":"Menyarankan pinjol lain yang bunganya kecil","s":2},{"t":"Menyarankan kabur dari penagih","s":1}],"ex":"Jeratan pinjol diputus dengan disiplin anggaran dan konseling, bukan utang baru."},
{"id":"TKP-3867","q":"Beredar di internet game online berkedok hadiah yang ternyata mengarahkan pemain ke situs judi. Anak tetangga mulai memainkannya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengedukasi orang tua tentang modus itu dan melaporkan aplikasi ke platform","s":5},{"t":"Mengingatkan orang tua anak tersebut","s":4},{"t":"Membiarkan karena hanya game","s":3},{"t":"Ikut memainkan untuk memastikan","s":2},{"t":"Menyebarkan game itu karena hadiahnya menarik","s":1}],"ex":"Game berkedok hadiah adalah pintu masuk judol bagi anak; edukasi orang tua dan laporkan aplikasinya."},
{"id":"TKP-3868","q":"Seseorang meminta memakai rekening bank Anda untuk menampung transaksi dengan imbalan komisi, diduga terkait judi online di internet. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak tegas karena berisiko jerat pidana pencucian uang, dan melaporkan tawaran itu","s":5},{"t":"Menolak tawaran tersebut","s":4},{"t":"Menerima untuk satu kali saja","s":3},{"t":"Menerima karena butuh tambahan penghasilan","s":2},{"t":"Menerima dan mengajak rekan lain","s":1}],"ex":"Rekening yang dipakai menampung dana judol menyeret pemilik ke pidana pencucian uang."},
{"id":"TKP-3869","q":"Rekan sering mangkir kerja diduga karena begadang bermain judi online di internet. Kinerjanya menurun dan beban kerja menumpuk ke Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur rekan secara privat dan melaporkan ke atasan bila tidak ada perbaikan","s":5},{"t":"Menegur rekan agar memperbaiki kehadiran","s":4},{"t":"Mengerjakan tugasnya diam-diam","s":3},{"t":"Mengeluh ke rekan lain","s":2},{"t":"Ikut mangkir sebagai protes","s":1}],"ex":"Kemangkiran akibat judol diselesaikan lewat teguran privat lalu jalur kedinasan bila berlanjut."},
{"id":"TKP-3870","q":"Unit Anda mencanangkan kampanye digital internal anti judi online dan pinjol ilegal. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung aktif, ikut menyosialisasikan, dan menjadi teladan bebas judol","s":5},{"t":"Mendukung kampanye tersebut","s":4},{"t":"Netral karena merasa tidak terkait","s":3},{"t":"Menolak karena dianggap mengada-ada","s":2},{"t":"Mengejek kampanye itu","s":1}],"ex":"Kampanye anti-judol butuh keteladanan ASN; dukung aktif dan jadilah contoh."},
{"id":"TKP-3871","q":"Rekan meminta tolong menghapus riwayat akses judi online via internet di komputer dinas yang ia pakai bersama Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak dan melaporkan penyalahgunaan komputer dinas ke unit TI","s":5},{"t":"Menolak membantu menghapus","s":4},{"t":"Menghapuskan diam-diam","s":3},{"t":"Menghapus dengan imbalan","s":2},{"t":"Membantu menyembunyikan jejaknya","s":1}],"ex":"Membantu menghapus jejak pelanggaran adalah pelanggaran tersendiri; laporkan penyalahgunaan aset dinas."},
{"id":"TKP-3872","q":"Aplikasi pinjaman yang Anda unduh meminta izin akses ke kontak, galeri, dan lokasi sekaligus. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak memberi izin berlebihan, menghapus aplikasi, dan memakai layanan keuangan resmi","s":5},{"t":"Menghapus aplikasi tersebut","s":4},{"t":"Memberi sebagian izin yang diminta","s":3},{"t":"Memberi semua izin agar cepat cair","s":2},{"t":"Memberi izin dan mengajukan pinjaman besar","s":1}],"ex":"Izin akses berlebihan adalah ciri pinjol predator; tolak dan hapus aplikasinya."},
{"id":"TKP-3873","q":"Akun media sosial gencar mempromosikan judi online dengan testimoni kemenangan besar setiap hari. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan akun ke platform dan tidak terpancing testimoni palsu","s":5},{"t":"Mengabaikan promosi tersebut","s":4},{"t":"Mencoba dengan modal kecil","s":3},{"t":"Meneruskan ke teman yang suka coba-coba","s":2},{"t":"Mendaftar karena testimoninya meyakinkan","s":1}],"ex":"Testimoni kemenangan judol adalah umpan pemasaran; laporkan akun promosinya."},
{"id":"TKP-3874","q":"Seorang pegawai menerima ancaman via WhatsApp dari bandar judi online karena kalah besar dan berutang. Ia ketakutan dan meminta saran Anda. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan melapor ke polisi, tidak membayar dengan cara melanggar hukum, dan mencari bantuan pemulihan","s":5},{"t":"Menyarankan melapor ke polisi","s":4},{"t":"Menyarankan membayar diam-diam","s":3},{"t":"Menyarankan kabur sementara","s":2},{"t":"Menyarankan meminjam untuk membayar bandar","s":1}],"ex":"Ancaman bandar judol adalah pidana; korban harus melapor ke polisi dan menjalani pemulihan."},
{"id":"TKP-3875","q":"Anda diminta mengisi penyuluhan digital bahaya judi online dan pinjol ilegal untuk keluarga besar. Pendekatan paling tepat adalah ....","opts":[{"t":"Menyampaikan dengan bahasa sederhana, contoh nyata, dan solusi bila sudah terjerat","s":5},{"t":"Menyampaikan bahayanya secara umum","s":4},{"t":"Menakut-nakuti dengan hukuman penjara","s":3},{"t":"Membacakan aturan perundangan saja","s":2},{"t":"Menolak karena bukan keahlian Anda","s":1}],"ex":"Penyuluhan efektif memakai bahasa sederhana, contoh nyata, dan jalan keluar bagi yang terjerat."},
{"id":"TKP-3876","q":"Layar komputer Anda tiba-tiba terkunci dengan pesan ransomware meminta tebusan bitcoin agar data bisa dibuka kembali. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak membayar, memutus koneksi jaringan, dan segera melaporkan ke unit TI","s":5},{"t":"Memutus koneksi dan menunggu bantuan TI","s":4},{"t":"Merestart komputer berharap kembali normal","s":3},{"t":"Membayar tebusan kecil agar cepat selesai","s":2},{"t":"Membayar tebusan sesuai permintaan","s":1}],"ex":"Ransomware tidak boleh dibayar; isolasi perangkat dan laporkan ke TI agar penyebaran terhenti."},
{"id":"TKP-3877","q":"Email phishing dari alamat mirip vendor berisi lampiran program berekstensi .exe dengan nama tagihan.pdf.exe. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak membuka lampiran, memverifikasi ke vendor resmi, dan melaporkan ke TI","s":5},{"t":"Menghapus email tanpa membuka lampiran","s":4},{"t":"Membuka lampiran di HP saja","s":3},{"t":"Meneruskan ke bagian keuangan","s":2},{"t":"Membuka lampiran untuk melihat tagihannya","s":1}],"ex":"Ekstensi ganda .pdf.exe adalah malware; verifikasi ke vendor resmi sebelum bertindak."},
{"id":"TKP-3878","q":"Rekan hendak mencolokkan flashdisk milik tamu ke komputer dinas untuk menyalin presentasi digital. Tindakan paling tepat adalah ....","opts":[{"t":"Mencegahnya, menyarankan pemindaian antivirus dulu atau memakai media berbagi yang aman","s":5},{"t":"Menyarankan memakai laptop pribadi saja","s":4},{"t":"Membiarkan karena hanya presentasi","s":3},{"t":"Mencolokkan dulu baru dipindai","s":2},{"t":"Ikut menyalin file dari flashdisk itu","s":1}],"ex":"Media asing wajib dipindai sebelum menyentuh komputer dinas; malware menyebar lewat USB."},
{"id":"TKP-3879","q":"Komputer dinas yang terhubung internet terus menampilkan pemberitahuan pembaruan keamanan, tetapi rekan menundanya berminggu-minggu agar tidak restart. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan segera memasang pembaruan karena menutup celah keamanan","s":5},{"t":"Menyarankan memasang saat jam istirahat","s":4},{"t":"Membiarkan sampai ada waktu luang","s":3},{"t":"Menyarankan menonaktifkan notifikasinya","s":2},{"t":"Menyarankan mengabaikan selamanya","s":1}],"ex":"Pembaruan keamanan menutup celah yang dieksploitasi peretas; penundaan berisiko."},
{"id":"TKP-3880","q":"Unit Anda menyimpan arsip digital penting bertahun-tahun tanpa pernah dicadangkan. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan jadwal pencadangan rutin dan menyimpannya di media terpisah yang aman","s":5},{"t":"Menyalin arsip ke flashdisk pribadi","s":4},{"t":"Membiarkan karena selama ini aman","s":3},{"t":"Menghapus arsip lama agar hemat","s":2},{"t":"Mengunggah arsip ke penyimpanan gratis pribadi","s":1}],"ex":"Tanpa backup, ransomware atau kerusakan menghapus arsip permanen; cadangkan rutin di media aman."},
{"id":"TKP-3881","q":"Anda mendapati layanan akses jarak jauh komputer kantor aktif tanpa VPN dan bisa dijangkau dari internet. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan temuan ke unit TI agar akses diamankan atau ditutup","s":5},{"t":"Menonaktifkannya sendiri bila bisa","s":4},{"t":"Membiarkan karena memudahkan kerja jarak jauh","s":3},{"t":"Memanfaatkan untuk kerja dari rumah","s":2},{"t":"Memberi tahu rekan agar ikut memakai","s":1}],"ex":"Akses jarak jauh terbuka ke internet adalah pintu masuk peretas; wajib diamankan lewat VPN."},
{"id":"TKP-3882","q":"Kata sandi WiFi internal kantor disebar rekan ke tamu-tamu agar mudah internetan. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan rekan, meminta penggantian kata sandi, dan mengusulkan jaringan tamu terpisah","s":5},{"t":"Mengingatkan rekan agar tidak menyebar lagi","s":4},{"t":"Mendiamkan karena kasihan pada tamu","s":3},{"t":"Ikut membagikan ke tamu lain","s":2},{"t":"Menempel kata sandi di dinding agar praktis","s":1}],"ex":"Kredensial jaringan internal yang tersebar membuka akses ilegal; sediakan jaringan tamu terpisah."},
{"id":"TKP-3883","q":"Anda menerima notifikasi login via aplikasi ke email dinas dari perangkat dan kota yang tidak dikenal. Tindakan paling tepat adalah ....","opts":[{"t":"Segera mengganti kata sandi dari perangkat aman, mengaktifkan verifikasi dua langkah, dan melapor ke TI","s":5},{"t":"Mengganti kata sandi secepatnya","s":4},{"t":"Mengabaikan karena mungkin kesalahan sistem","s":3},{"t":"Menunggu sampai ada keanehan","s":2},{"t":"Mengklik tautan di notifikasi untuk memeriksa","s":1}],"ex":"Notifikasi login asing menandakan akun dibobol; amankan segera dari perangkat tepercaya."},
{"id":"TKP-3884","q":"Rekan memasang perangkat lunak bajakan di komputer dinas yang terhubung internet agar tidak perlu membeli lisensi. Saran paling tepat adalah ....","opts":[{"t":"Melarang karena melanggar hukum dan rawan malware, menyarankan pengajuan lisensi resmi","s":5},{"t":"Menyarankan menghapus perangkat lunak itu","s":4},{"t":"Membiarkan karena menghemat anggaran","s":3},{"t":"Meminta salinannya untuk komputer Anda","s":2},{"t":"Ikut memasang di komputer Anda","s":1}],"ex":"Software bajakan melanggar hukum dan kerap disusupi malware; ajukan lisensi resmi."},
{"id":"TKP-3885","q":"Terjadi dugaan kebocoran data di sistem aplikasi instansi Anda. Sebagai pegawai, langkah paling tepat adalah ....","opts":[{"t":"Mengikuti prosedur insiden: melapor ke pimpinan dan unit TI/CSIRT, tidak menyembunyikan kejadian","s":5},{"t":"Melaporkan ke atasan langsung","s":4},{"t":"Mendiamkan agar tidak panik","s":3},{"t":"Menghapus jejak agar tidak disalahkan","s":2},{"t":"Menyebarkan kabar ke media sosial","s":1}],"ex":"Insiden siber wajib dilaporkan lewat prosedur resmi agar ditangani cepat dan tepat."},
{"id":"TKP-3886","q":"Terkena ransomware, berkas-berkas penting di komputer unit terenkripsi dan pelaku meminta tebusan dalam mata uang kripto. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak membayar, mengisolasi sistem, melaporkan ke TI dan aparat, lalu memulihkan dari cadangan","s":5},{"t":"Melaporkan ke unit TI","s":4},{"t":"Bernegosiasi menurunkan tebusan","s":3},{"t":"Membayar sebagian dulu","s":2},{"t":"Membayar penuh agar data kembali","s":1}],"ex":"Membayar tebusan tak menjamin data kembali dan mendanai kejahatan; pulihkan dari backup."},
{"id":"TKP-3887","q":"Di bandara tersedia stasiun pengisian daya USB umum. Baterai HP dinas Anda hampir habis dan ada dokumen digital penting. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mencolokkan ke USB umum; memakai powerbank atau charger ke stopkontak listrik","s":5},{"t":"Menunggu sampai menemukan stopkontak","s":4},{"t":"Mencolokkan sebentar saja","s":3},{"t":"Mencolokkan karena butuh mendesak","s":2},{"t":"Mencolokkan sambil transfer data","s":1}],"ex":"USB publik bisa mencuri data (juice jacking); pakai charger ke stopkontak atau powerbank sendiri."},
{"id":"TKP-3888","q":"Rekan mengirimkan kata sandi akun aplikasi dinas lewat grup WhatsApp agar mudah diingat bersama. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta pesan dihapus, mengganti kata sandi, dan mengingatkan agar kredensial tak dibagikan","s":5},{"t":"Meminta rekan menghapus pesan itu","s":4},{"t":"Menyimpan kata sandi itu baik-baik","s":3},{"t":"Membagikan ulang ke grup lain yang butuh","s":2},{"t":"Membiarkan karena praktis","s":1}],"ex":"Kata sandi di grup chat sama dengan disebar; hapus, ganti, dan kelola lewat pengelola kata sandi."},
{"id":"TKP-3889","q":"Email phishing tak dikenal mengirim berkas spreadsheet dan meminta Anda mengaktifkan makro agar bisa dibuka. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mengaktifkan makro, tidak membuka berkas, dan melaporkan ke TI","s":5},{"t":"Menghapus email tersebut","s":4},{"t":"Membuka tanpa mengaktifkan makro","s":3},{"t":"Mengaktifkan makro sebentar saja","s":2},{"t":"Mengaktifkan makro sesuai instruksi","s":1}],"ex":"Makro adalah vektor malware klasik; jangan pernah aktifkan dari pengirim tak dikenal."},
{"id":"TKP-3890","q":"Saat rapat daring, Anda tidak sadar masih berbagi layar yang menampilkan data pribadi warga. Peserta sudah banyak. Tindakan paling tepat adalah ....","opts":[{"t":"Segera menghentikan berbagi layar, meminta peserta menghapus tangkapan bila ada, dan melaporkan insiden","s":5},{"t":"Segera menghentikan berbagi layar","s":4},{"t":"Melanjutkan karena sudah terlanjur","s":3},{"t":"Berpura-pura tidak terjadi apa-apa","s":2},{"t":"Mengabaikan dan melanjutkan presentasi","s":1}],"ex":"Keterbukaan data tak sengaja harus segera dihentikan dan dilaporkan sebagai insiden."},
{"id":"TKP-3891","q":"Laptop dinas berisi data digital penting tertinggal di taksi dan tidak kembali. Tindakan paling tepat adalah ....","opts":[{"t":"Segera melapor ke atasan dan TI untuk penguncian jarak jauh serta penggantian kredensial","s":5},{"t":"Melaporkan kehilangan ke atasan","s":4},{"t":"Mencoba menghubungi sopir taksi dulu","s":3},{"t":"Menunggu siapa tahu dikembalikan","s":2},{"t":"Mendiamkan karena takut disalahkan","s":1}],"ex":"Perangkat dinas hilang wajib dilaporkan cepat agar data bisa dikunci dan kredensial diganti."},
{"id":"TKP-3892","q":"Rekan memasang aplikasi kendali jarak jauh tak resmi di komputer dinas agar bisa diakses dari rumah. Saran paling tepat adalah ....","opts":[{"t":"Melarang dan memintanya memakai solusi resmi instansi yang diawasi TI","s":5},{"t":"Menyarankan menghapus aplikasi itu","s":4},{"t":"Membiarkan karena membantu pekerjaan","s":3},{"t":"Meminta diajari cara memasangnya","s":2},{"t":"Ikut memasang di komputer Anda","s":1}],"ex":"Aplikasi remote tak resmi membuka celah peretasan; akses jarak jauh hanya lewat solusi resmi."},
{"id":"TKP-3893","q":"Anda menemukan aturan penerusan email asing di kotak surat digital dinas yang meneruskan semua pesan ke alamat tak dikenal. Tindakan paling tepat adalah ....","opts":[{"t":"Menghapus aturan itu, mengganti kata sandi, dan melaporkan dugaan peretasan ke TI","s":5},{"t":"Menghapus aturan penerusan itu","s":4},{"t":"Membiarkan karena mungkin aturan lama","s":3},{"t":"Mengubah tujuan penerusan ke email Anda","s":2},{"t":"Mengabaikan temuan itu","s":1}],"ex":"Aturan penerusan asing adalah tanda akun dibobol; hapus, amankan akun, dan laporkan."},
{"id":"TKP-3894","q":"Rekan mengunduh aplikasi perkantoran dari situs unduhan gratis, bukan situs resmi pengembang. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan menghapusnya dan mengunduh ulang dari situs resmi pengembang","s":5},{"t":"Menyarankan memindai dengan antivirus","s":4},{"t":"Membiarkan karena aplikasinya berjalan normal","s":3},{"t":"Meminta salinan installernya","s":2},{"t":"Ikut mengunduh dari situs yang sama","s":1}],"ex":"Installer dari situs tak resmi kerap disusupi malware; unduh hanya dari sumber resmi."},
{"id":"TKP-3895","q":"Situs layanan digital instansi Anda tidak bisa diakses karena serangan yang membanjiri trafik. Warga mengeluh. Sikap paling tepat adalah ....","opts":[{"t":"Melaporkan ke unit TI, mengikuti prosedur pemulihan, dan menginformasikan warga lewat kanal resmi","s":5},{"t":"Melaporkan gangguan ke unit TI","s":4},{"t":"Menunggu situs pulih sendiri","s":3},{"t":"Menyalahkan penyedia hosting di media sosial","s":2},{"t":"Mematikan server sendiri tanpa koordinasi","s":1}],"ex":"Serangan banjir trafik ditangani TI sesuai prosedur; komunikasikan status ke warga lewat kanal resmi."},
{"id":"TKP-3896","q":"Rekan memakai kata sandi kantor123 untuk semua akun digital dinasnya karena mudah diingat. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan mengganti dengan kata sandi kuat yang unik tiap akun plus verifikasi dua langkah","s":5},{"t":"Menyarankan mengganti kata sandinya","s":4},{"t":"Membiarkan karena hak rekan","s":3},{"t":"Ikut memakai pola kata sandi yang sama","s":2},{"t":"Menyebarkan kata sandinya agar mudah diingat","s":1}],"ex":"Kata sandi lemah yang dipakai ulang mudah dibobol; gunakan yang kuat, unik, dan 2FA."},
{"id":"TKP-3897","q":"Dokumen internal instansi tersebar lewat tautan berbagi berkas digital publik yang dibuat rekan agar mudah diakses. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta tautan dicabut, membatasi akses dokumen, dan mengingatkan tentang klasifikasi informasi","s":5},{"t":"Meminta rekan mencabut tautan itu","s":4},{"t":"Membiarkan karena memudahkan kerja","s":3},{"t":"Ikut menyebarkan tautannya","s":2},{"t":"Mengunggah dokumen lain ke tautan publik","s":1}],"ex":"Dokumen internal di tautan publik melanggar klasifikasi informasi; cabut dan batasi aksesnya."},
{"id":"TKP-3898","q":"Dalam simulasi phishing internal, beberapa rekan gagal dan datanya tercatat. Sikap paling tepat terhadap mereka adalah ....","opts":[{"t":"Menjadikannya bahan edukasi tanpa mempermalukan, agar kewaspadaan meningkat","s":5},{"t":"Memberi pelatihan tambahan","s":4},{"t":"Menegur mereka di depan umum","s":3},{"t":"Mengusulkan sanksi berat","s":2},{"t":"Menyebarkan nama yang gagal","s":1}],"ex":"Simulasi phishing bertujuan edukasi; permalukan justru menurunkan keterbukaan melapor."},
{"id":"TKP-3899","q":"Kamera pengawas digital kantor masih memakai kata sandi bawaan pabrik yang mudah ditebak. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan ke unit TI agar kata sandi diganti dan perangkat diamankan","s":5},{"t":"Mengganti kata sandinya bila Anda bisa","s":4},{"t":"Membiarkan karena bukan tugas Anda","s":3},{"t":"Menyebarkan kata sandinya ke rekan","s":2},{"t":"Memanfaatkan untuk memantau ruangan","s":1}],"ex":"Perangkat dengan kredensial bawaan mudah dibajak; amankan lewat unit TI."},
{"id":"TKP-3900","q":"Unit Anda mengusulkan prosedur penanganan insiden siber: siapa melapor ke siapa saat serangan terjadi. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan ikut menyusun alur pelaporan yang jelas serta mensosialisasikannya","s":5},{"t":"Mendukung usulan prosedur itu","s":4},{"t":"Netral karena merasa tidak akan terjadi","s":3},{"t":"Menolak karena menambah birokrasi","s":2},{"t":"Mengabaikan usulan tersebut","s":1}],"ex":"Prosedur insiden siber mempercepat respons; dukung, susun, dan sosialisasikan."},
{"id":"TKP-3901","q":"Seorang warga lanjut usia kebingungan memakai aplikasi antrean online dan hampir pulang tanpa terlayani. Tindakan paling tepat adalah ....","opts":[{"t":"Mendampingi dengan sabar sampai selesai, lalu mengusulkan pendampingan khusus lansia","s":5},{"t":"Membantu warga itu sampai selesai","s":4},{"t":"Meminta warga belajar dari anaknya","s":3},{"t":"Menyuruh warga kembali lain waktu","s":2},{"t":"Membiarkan warga pulang tanpa terlayani","s":1}],"ex":"Transformasi digital harus inklusif; dampingi kelompok rentan dan usulkan layanan pendampingan."},
{"id":"TKP-3902","q":"Warga menolak surat keterangan digital bertanda tangan elektronik karena menganggap tidak sah tanpa tanda tangan basah. Sikap paling tepat adalah ....","opts":[{"t":"Menjelaskan tanda tangan elektronik tersertifikasi sah secara hukum dan menunjukkan dasarnya","s":5},{"t":"Menjelaskan tanda tangan digital itu sah","s":4},{"t":"Membuatkan versi tanda tangan basah agar cepat","s":3},{"t":"Membiarkan warga mencari instansi lain","s":2},{"t":"Ikut meragukan keabsahan tanda tangan digital","s":1}],"ex":"Tanda tangan elektronik tersertifikasi memiliki kekuatan hukum; edukasi warga dengan dasar yang jelas."},
{"id":"TKP-3903","q":"Rekan masih mencetak semua dokumen digital untuk diarsipkan fisik, padahal sistem e-office sudah berjalan. Saran paling tepat adalah ....","opts":[{"t":"Mengajak memanfaatkan e-office dan mengusulkan sosialisasi pengurangan kertas","s":5},{"t":"Menyarankan mengurangi cetakan","s":4},{"t":"Membiarkan karena kebiasaan rekan","s":3},{"t":"Ikut mencetak agar seragam","s":2},{"t":"Mengejek rekan yang gaptek","s":1}],"ex":"E-office mengurangi kertas dan mempercepat alur; ajak rekan bertransisi dengan sosialisasi."},
{"id":"TKP-3904","q":"Data kependudukan berbeda antara aplikasi dinas Anda dan dinas lain karena tidak terhubung. Warga dirugikan. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan integrasi data antar aplikasi sesuai prinsip Satu Data Indonesia","s":5},{"t":"Melaporkan masalah ke unit TI","s":4},{"t":"Meminta warga mengurus ke dua dinas","s":3},{"t":"Membiarkan karena bukan wewenang Anda","s":2},{"t":"Mengubah data manual agar cocok","s":1}],"ex":"Interoperabilitas dan Satu Data mencegah warga dirugikan data yang tidak sinkron."},
{"id":"TKP-3905","q":"Sebagian warga tidak punya ponsel pintar sehingga tak bisa mengakses layanan digital baru. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan kanal alternatif seperti loket bantuan dan pendampingan agar tak ada yang tertinggal","s":5},{"t":"Membantu warga itu secara manual","s":4},{"t":"Menyarankan warga membeli ponsel pintar","s":3},{"t":"Menyuruh warga minta tolong tetangga","s":2},{"t":"Menolak melayani yang tak pakai aplikasi","s":1}],"ex":"Layanan digital wajib menyediakan alternatif inklusif bagi yang terkendala perangkat."},
{"id":"TKP-3906","q":"Layanan tatap muka dihapus total dan diganti aplikasi, tetapi banyak warga protes. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan masa transisi dengan kedua kanal berjalan sampai warga siap","s":5},{"t":"Mempertahankan loket bantuan sementara","s":4},{"t":"Memaksa warga memakai aplikasi","s":3},{"t":"Mengabaikan protes warga","s":2},{"t":"Menutup aplikasi dan kembali manual","s":1}],"ex":"Digitalisasi butuh transisi bertahap; paksakan sekaligus justru menurunkan kualitas layanan."},
{"id":"TKP-3907","q":"Gudang arsip fisik menumpuk dan digitalisasi berjalan lambat. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan prioritas digitalisasi arsip aktif dan jadwal yang realistis","s":5},{"t":"Mendukung percepatan digitalisasi","s":4},{"t":"Membiarkan menumpuk","s":3},{"t":"Membakar arsip lama diam-diam","s":2},{"t":"Menolak terlibat digitalisasi","s":1}],"ex":"Digitalisasi arsip diprioritaskan pada arsip aktif dengan jadwal realistis."},
{"id":"TKP-3908","q":"Aplikasi layanan sering error saat jam sibuk dan warga mengeluh ke Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Meneruskan keluhan ke pengelola aplikasi, memberi solusi sementara, dan menginformasikan progres","s":5},{"t":"Melaporkan gangguan ke unit TI","s":4},{"t":"Meminta warga mencoba lagi nanti","s":3},{"t":"Menyalahkan pengembang aplikasi","s":2},{"t":"Mengabaikan keluhan warga","s":1}],"ex":"Gangguan aplikasi ditangani lewat pelaporan resmi disertai solusi sementara dan komunikasi progres."},
{"id":"TKP-3909","q":"Rekan senior enggan mempelajari aplikasi kerja baru dan tetap memakai cara lama yang lambat. Saran paling tepat adalah ....","opts":[{"t":"Menawarkan bantuan belajar privat dan mengusulkan pelatihan yang ramah pemula","s":5},{"t":"Membantu rekan mempelajari aplikasi","s":4},{"t":"Mengerjakan tugas digital rekan itu","s":3},{"t":"Membiarkan rekan tertinggal","s":2},{"t":"Melaporkan rekan sebagai pembangkang","s":1}],"ex":"Adopsi teknologi butuh pendampingan sabar, bukan paksaan atau ejekan."},
{"id":"TKP-3910","q":"Warga kesal karena diminta mengisi data pribadi yang sama di setiap loket yang berbeda. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan pemakaian data bersama antar loket agar warga cukup mengisi sekali","s":5},{"t":"Menyampaikan keluhan ke pimpinan","s":4},{"t":"Meminta warga bersabar mengisi ulang","s":3},{"t":"Menyalahkan sistem yang ada","s":2},{"t":"Mengabaikan keluhan warga","s":1}],"ex":"Prinsip sekali isi berlaku banyak layanan; integrasi data mengurangi beban warga."},
{"id":"TKP-3911","q":"Pembayaran retribusi beralih ke digital, tetapi pedagang kecil hanya punya uang tunai. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan tetap membuka kanal tunai terbatas sambil mengedukasi pembayaran digital","s":5},{"t":"Melayani tunai untuk kasus itu","s":4},{"t":"Menolak pembayaran tunai","s":3},{"t":"Menyuruh pedagang ke bank dulu","s":2},{"t":"Membiarkan pedagang tidak membayar","s":1}],"ex":"Transisi pembayaran digital tetap membuka kanal tunai terbatas bagi yang belum siap."},
{"id":"TKP-3912","q":"Pemberitahuan digital jadwal pelayanan tidak dibaca warga sehingga banyak yang datang di luar jadwal. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan pengingat multi-kanal: aplikasi, SMS, dan papan pengumuman fisik","s":5},{"t":"Menambah pengumuman fisik di kantor","s":4},{"t":"Menyalahkan warga yang tidak membaca","s":3},{"t":"Menghapus fitur pemberitahuan","s":2},{"t":"Membiarkan kekacauan jadwal","s":1}],"ex":"Komunikasi efektif memakai multi-kanal menyesuaikan kebiasaan warga."},
{"id":"TKP-3913","q":"Sertifikat elektronik Anda untuk tanda tangan digital hampir kedaluwarsa. Tindakan paling tepat adalah ....","opts":[{"t":"Segera memperpanjang lewat penyelenggara resmi sebelum kedaluwarsa","s":5},{"t":"Memperpanjang minggu ini juga","s":4},{"t":"Menunggu sampai benar-benar kedaluwarsa","s":3},{"t":"Meminjam sertifikat rekan sementara","s":2},{"t":"Mengabaikan sampai ada yang komplain","s":1}],"ex":"Sertifikat kedaluwarsa membuat tanda tangan digital tidak valid; perpanjang tepat waktu."},
{"id":"TKP-3914","q":"Rekan menyimpan arsip digital dinas di ponsel pribadinya agar mudah dikerjakan di rumah. Saran paling tepat adalah ....","opts":[{"t":"Melarang karena berisiko bocor, menyarankan memakai perangkat dan akses resmi","s":5},{"t":"Menyarankan memindahkan ke perangkat dinas","s":4},{"t":"Membiarkan karena praktis","s":3},{"t":"Ikut menyimpan di ponsel Anda","s":2},{"t":"Menyebarkan arsip ke grup agar mudah","s":1}],"ex":"Arsip dinas di perangkat pribadi rawan bocor dan hilang; gunakan perangkat dan akses resmi."},
{"id":"TKP-3915","q":"Pimpinan meminta dashboard digital capaian layanan yang bisa dipantau publik. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan membantu menyiapkan data yang akurat serta mudah dipahami publik","s":5},{"t":"Mendukung usulan dashboard itu","s":4},{"t":"Netral karena menambah pekerjaan","s":3},{"t":"Menolak karena data sensitif","s":2},{"t":"Memalsukan angka agar terlihat bagus","s":1}],"ex":"Dashboard publik meningkatkan transparansi; dukung dengan data akurat."},
{"id":"TKP-3916","q":"Ada usulan layanan keliling diganti sepenuhnya aplikasi daring. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan kombinasi: aplikasi untuk yang mampu, layanan keliling untuk daerah terpencil","s":5},{"t":"Mempertahankan layanan keliling","s":4},{"t":"Setuju diganti total demi efisiensi","s":3},{"t":"Menolak mentah-mentah","s":2},{"t":"Tidak peduli dengan usulan itu","s":1}],"ex":"Daerah terpencil butuh layanan jemput bola; digital dan keliling saling melengkapi."},
{"id":"TKP-3917","q":"Warga difabel kesulitan mengoperasikan aplikasi layanan yang tidak ramah disabilitas. Tindakan paling tepat adalah ....","opts":[{"t":"Meneruskan masukan ke pengembang dan menyediakan pendampingan khusus sementara","s":5},{"t":"Membantu warga itu secara langsung","s":4},{"t":"Menyarankan warga memakai jasa orang lain","s":3},{"t":"Mengabaikan karena kasus langka","s":2},{"t":"Menyalahkan pengembang di media sosial","s":1}],"ex":"Aksesibilitas adalah hak; teruskan masukan perbaikan sambil beri pendampingan."},
{"id":"TKP-3918","q":"Surat digital dari instansi Anda ditolak instansi lain yang masih meminta cap basah. Tindakan paling tepat adalah ....","opts":[{"t":"Berkoordinasi antar instansi untuk standardisasi penerimaan dokumen digital","s":5},{"t":"Menjelaskan keabsahan surat digital ke instansi itu","s":4},{"t":"Membuatkan versi cap basah","s":3},{"t":"Membiarkan warga bolak-balik","s":2},{"t":"Ikut menuntut cap basah","s":1}],"ex":"Hambatan antar instansi diselesaikan dengan koordinasi standardisasi, bukan membebani warga."},
{"id":"TKP-3919","q":"Antrean online di aplikasi layanan diserobot calo yang memakai banyak akun untuk dijual nomor antreannya. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan ke pengelola aplikasi untuk penguatan verifikasi dan penindakan calo","s":5},{"t":"Melaporkan temuan ke atasan","s":4},{"t":"Membeli nomor antrean agar cepat","s":3},{"t":"Membiarkan karena sulit dibuktikan","s":2},{"t":"Ikut menjadi calo","s":1}],"ex":"Calo antrean digital diberantas lewat penguatan verifikasi dan penindakan tegas."},
{"id":"TKP-3920","q":"Dinas mengadakan pelatihan aplikasi baru khusus pegawai senior yang gagap teknologi. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan bersedia menjadi pendamping bila diminta","s":5},{"t":"Mendukung pelatihan itu","s":4},{"t":"Netral karena tidak ikut","s":3},{"t":"Mengejek pelatihan itu","s":2},{"t":"Menolak ikut membantu","s":1}],"ex":"Pelatihan inklusif menaikkan adopsi digital; dukung dan bersedia mendampingi."},
{"id":"TKP-3921","q":"Warga bingung membayar bea materai elektronik untuk dokumen digitalnya. Sikap paling tepat adalah ....","opts":[{"t":"Menjelaskan alur pembelian materai elektronik lewat kanal resmi dengan sabar","s":5},{"t":"Menunjukkan kanal resmi pembeliannya","s":4},{"t":"Menyuruh warga mencari sendiri","s":3},{"t":"Menjualkan materai dengan harga lebih","s":2},{"t":"Mengabaikan kebingungan warga","s":1}],"ex":"Edukasi sabar tentang materai elektronik mencegah warga jadi korban calo."},
{"id":"TKP-3922","q":"Angka statistik layanan berbeda antara laporan manual unit dan dashboard digital. Tindakan paling tepat adalah ....","opts":[{"t":"Menelusuri sumber perbedaan dan mengusulkan satu sumber data resmi","s":5},{"t":"Melaporkan perbedaan ke pimpinan","s":4},{"t":"Memakai angka yang terlihat bagus","s":3},{"t":"Membiarkan perbedaan itu","s":2},{"t":"Mengubah dashboard agar cocok","s":1}],"ex":"Satu data resmi mencegah kebijakan berbasis angka yang salah."},
{"id":"TKP-3923","q":"Warga meminta surat manual karena tidak percaya dokumen digital bisa dipertanggungjawabkan. Sikap paling tepat adalah ....","opts":[{"t":"Menjelaskan keabsahan dokumen digital dengan contoh verifikasinya, tanpa memaksa","s":5},{"t":"Menjelaskan dokumen digital itu sah","s":4},{"t":"Langsung membuatkan surat manual","s":3},{"t":"Menolak menjelaskan","s":2},{"t":"Ikut meragukan dokumen digital","s":1}],"ex":"Kepercayaan dibangun lewat penjelasan dan bukti verifikasi, bukan paksaan."},
{"id":"TKP-3924","q":"Hasil evaluasi kematangan digital instansi Anda masih rendah. Sikap paling tepat adalah ....","opts":[{"t":"Menjadikannya pemacu perbaikan: dukung program peningkatan dan ikut berkontribusi","s":5},{"t":"Mendukung program perbaikan","s":4},{"t":"Menyalahkan unit TI","s":3},{"t":"Menganggap evaluasi mengada-ada","s":2},{"t":"Menyembunyikan hasil evaluasi","s":1}],"ex":"Evaluasi rendah adalah cermin untuk berbenah, bukan untuk disembunyikan atau disalahkan."},
{"id":"TKP-3925","q":"Ada usulan membuat chatbot layanan digital untuk menjawab pertanyaan warga otomatis. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dengan kajian: pastikan jawaban akurat dan ada eskalasi ke petugas manusia","s":5},{"t":"Mendukung usulan chatbot itu","s":4},{"t":"Netral karena belum paham","s":3},{"t":"Menolak karena takut digantikan","s":2},{"t":"Mengabaikan usulan itu","s":1}],"ex":"Chatbot layanan efektif bila jawabannya akurat dan selalu ada jalur ke petugas manusia."},
{"id":"TKP-3926","q":"Rekan memakai aplikasi kecerdasan buatan gratis untuk membuat draf surat dinas. Sikap paling tepat adalah ....","opts":[{"t":"Membolehkan dengan syarat hasilnya diverifikasi dan tidak memasukkan data sensitif ke aplikasi","s":5},{"t":"Membolehkan asal dicek ulang","s":4},{"t":"Melarang total penggunaan AI","s":3},{"t":"Membiarkan tanpa peduli","s":2},{"t":"Ikut memasukkan data rahasia ke AI","s":1}],"ex":"AI boleh membantu draf, tetapi output wajib diverifikasi dan data sensitif dilarang diunggah."},
{"id":"TKP-3927","q":"Rekan memasukkan data pribadi warga ke chatbot AI gratis untuk dibuatkan rekap. Tindakan paling tepat adalah ....","opts":[{"t":"Melarang, meminta data dihapus, dan mengingatkan larangan mengunggah data pribadi ke layanan publik","s":5},{"t":"Menegur rekan agar tidak mengulangi","s":4},{"t":"Membiarkan karena praktis","s":3},{"t":"Ikut memakai cara yang sama","s":2},{"t":"Menyebarkan rekapnya ke grup","s":1}],"ex":"Data pribadi warga dilarang diunggah ke AI publik; pelanggaran privasi dan aturan perlindungan data."},
{"id":"TKP-3928","q":"Draf jawaban aplikasi AI yang mengarang aturan tidak ada dipakai rekan mentah-mentah untuk menjawab warga. Tindakan paling tepat adalah ....","opts":[{"t":"Mengoreksi jawaban, mengingatkan AI bisa berhalusinasi, dan mewajibkan verifikasi sumber","s":5},{"t":"Mengoreksi jawaban yang salah itu","s":4},{"t":"Membiarkan karena warga tidak tahu","s":3},{"t":"Ikut memakai jawaban AI mentah","s":2},{"t":"Menyalahkan AI atas kesalahan","s":1}],"ex":"AI dapat mengarang fakta; setiap output untuk publik wajib diverifikasi ke sumber resmi."},
{"id":"TKP-3929","q":"Ada usulan memakai sistem AI digital untuk menentukan penerima bantuan secara otomatis. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dengan syarat ada pengawasan manusia dan kriteria transparan yang bisa diaudit","s":5},{"t":"Mendukung usulan itu","s":4},{"t":"Menolak mentah-mentah","s":3},{"t":"Setuju penuh tanpa syarat","s":2},{"t":"Tidak peduli dengan usulan itu","s":1}],"ex":"Keputusan otomatis berdampak ke warga wajib transparan, bisa diaudit, dan diawasi manusia."},
{"id":"TKP-3930","q":"Anda memakai aplikasi AI untuk meringkas dokumen kebijakan setebal 200 halaman. Sikap paling tepat adalah ....","opts":[{"t":"Memanfaatkan ringkasan sebagai pijakan, lalu memverifikasi poin penting ke dokumen asli","s":5},{"t":"Memakai ringkasan lalu cek sekilas","s":4},{"t":"Mempercayai ringkasan sepenuhnya","s":3},{"t":"Menolak memakai AI","s":2},{"t":"Mengaku membaca dokumen asli","s":1}],"ex":"Ringkasan AI mempercepat kerja, tetapi poin penting tetap diverifikasi ke dokumen asli."},
{"id":"TKP-3931","q":"Petugas menjawab pertanyaan warga dengan menyalin jawaban aplikasi AI tanpa memeriksa, ternyata jawabannya keliru. Tindakan paling tepat adalah ....","opts":[{"t":"Mengoreksi informasi ke warga, meminta maaf, dan menetapkan verifikasi wajib sebelum menjawab","s":5},{"t":"Mengoreksi informasi yang salah","s":4},{"t":"Menyalahkan aplikasi AI","s":3},{"t":"Mendiamkan kesalahan itu","s":2},{"t":"Melanjutkan menjawab dengan AI","s":1}],"ex":"Informasi keliru ke warga harus dikoreksi terbuka; jawaban AI bukan kebenaran final."},
{"id":"TKP-3932","q":"Sistem AI digital yang dipakai menyaring berkas cenderung meloloskan pelamar dari daerah tertentu saja. Sikap paling tepat adalah ....","opts":[{"t":"Melaporkan dugaan bias, meminta audit, dan memastikan keputusan akhir di tangan manusia","s":5},{"t":"Melaporkan temuan ke atasan","s":4},{"t":"Membiarkan karena sistem yang memutuskan","s":3},{"t":"Memanfaatkan bias untuk kepentingan","s":2},{"t":"Menutup-nutupi temuan itu","s":1}],"ex":"Bias algoritma merugikan keadilan; audit dan kendali manusia wajib diterapkan."},
{"id":"TKP-3933","q":"Rekan mengunggah dokumen berlabel rahasia ke layanan AI online di internet untuk diterjemahkan. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan pelanggaran keamanan informasi dan meminta dokumen ditarik","s":5},{"t":"Menegur keras rekan tersebut","s":4},{"t":"Meminta salinan terjemahannya","s":3},{"t":"Membiarkan karena sudah terjadi","s":2},{"t":"Ikut mengunggah dokumen lain","s":1}],"ex":"Dokumen rahasia yang diunggah ke layanan publik adalah pelanggaran keamanan informasi."},
{"id":"TKP-3934","q":"Rekan mengandalkan aplikasi AI untuk menghitung anggaran kegiatan tanpa memeriksa ulang. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan memeriksa ulang hitungan secara manual karena AI bisa salah berhitung","s":5},{"t":"Menyarankan cek ulang sekilas","s":4},{"t":"Mempercayai hitungan AI","s":3},{"t":"Ikut memakai tanpa cek","s":2},{"t":"Menandatangani anggaran itu","s":1}],"ex":"Angka anggaran menyangkut uang negara; hitungan AI wajib diverifikasi manual."},
{"id":"TKP-3935","q":"Rapat dinas direkam dan ditranskrip otomatis oleh aplikasi AI. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan peserta tahu direkam, transkrip disimpan aman, dan data sensitif tidak tersebar","s":5},{"t":"Memberi tahu peserta bahwa rapat direkam","s":4},{"t":"Membiarkan tanpa pemberitahuan","s":3},{"t":"Mengunggah transkrip ke cloud pribadi","s":2},{"t":"Menyebarkan transkrip ke media sosial","s":1}],"ex":"Perekaman rapat wajib transparan ke peserta dan hasilnya dikelola aman."},
{"id":"TKP-3936","q":"Chatbot layanan digital menjawab pertanyaan warga dengan informasi ngawur dan warga marah. Tindakan paling tepat adalah ....","opts":[{"t":"Mengambil alih dengan petugas manusia, mengoreksi info, dan melaporkan kesalahan ke pengelola","s":5},{"t":"Meminta maaf dan menjawab manual","s":4},{"t":"Menyalahkan warga yang bertanya aneh","s":3},{"t":"Mematikan chatbot diam-diam","s":2},{"t":"Membiarkan chatbot terus menjawab","s":1}],"ex":"Chatbot yang ngawur harus segera diambil alih manusia dan diperbaiki basis pengetahuannya."},
{"id":"TKP-3937","q":"Rekan mengklaim laporan buatan aplikasi AI sebagai karya tulisnya sendiri untuk angka kredit. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan itu melanggar etik karya tulis dan menyarankan transparan tentang bantuan AI","s":5},{"t":"Menyarankan tidak mengulangi","s":4},{"t":"Membiarkan karena umum terjadi","s":3},{"t":"Ikut memakai cara yang sama","s":2},{"t":"Melaporkan dengan niat menjatuhkan","s":1}],"ex":"Karya tulis menuntut kejujuran; penggunaan AI harus transparan sesuai aturan."},
{"id":"TKP-3938","q":"Ada tawaran memakai AI untuk memindai hoaks yang menyerang instansi. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dengan tetap verifikasi manusia sebelum merilis klarifikasi","s":5},{"t":"Mendukung pemakaian AI itu","s":4},{"t":"Menolak karena takut salah","s":3},{"t":"Menyerahkan sepenuhnya ke AI","s":2},{"t":"Mengabaikan tawaran itu","s":1}],"ex":"AI mempercepat deteksi hoaks, tetapi klarifikasi resmi tetap lewat verifikasi manusia."},
{"id":"TKP-3939","q":"Unit Anda membahas aturan penggunaan aplikasi AI bagi pegawai. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung aturan jelas: boleh untuk bantu kerja, dilarang untuk data sensitif dan keputusan final sepihak","s":5},{"t":"Mendukung dibuatnya aturan","s":4},{"t":"Netral karena belum paham AI","s":3},{"t":"Menolak diatur-atur","s":2},{"t":"Mengabaikan pembahasan","s":1}],"ex":"Aturan penggunaan AI memberi rambu jelas: alat bantu ya, pengganti tanggung jawab tidak."},
{"id":"TKP-3940","q":"Rekan memakai aplikasi AI untuk menerjemahkan dokumen kerja sama luar negeri. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan hasil terjemahan dicek ulang oleh penerjemah kompeten sebelum dipakai resmi","s":5},{"t":"Menyarankan cek ulang sekilas","s":4},{"t":"Memakai terjemahan apa adanya","s":3},{"t":"Menolak memakai AI","s":2},{"t":"Mengirim terjemahan mentah ke mitra","s":1}],"ex":"Terjemahan dokumen resmi berdampak hukum; hasil AI wajib dicek penerjemah kompeten."},
{"id":"TKP-3941","q":"Pegawai makin enggan berpikir karena semua diserahkan ke aplikasi AI. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan AI alat bantu; nalar dan tanggung jawab tetap milik manusia","s":5},{"t":"Mengurangi ketergantungan pada AI","s":4},{"t":"Membiarkan karena efisien","s":3},{"t":"Melarang total pemakaian AI","s":2},{"t":"Ikut menyerahkan semua ke AI","s":1}],"ex":"Ketergantungan buta pada AI melemahkan nalar; gunakan sebagai alat bantu yang dikritisi."},
{"id":"TKP-3942","q":"Aplikasi AI merekomendasikan menolak pengajuan warga dengan alasan yang tidak masuk akal. Tindakan paling tepat adalah ....","opts":[{"t":"Mengabaikan rekomendasi janggal, memeriksa manual, dan memutuskan berbasis aturan","s":5},{"t":"Memeriksa manual pengajuan itu","s":4},{"t":"Mengikuti rekomendasi AI","s":3},{"t":"Menolak pengajuan sesuai saran AI","s":2},{"t":"Menyalahkan AI di depan warga","s":1}],"ex":"Rekomendasi AI yang janggal wajib dikesampingkan; keputusan mengikuti aturan dan akal sehat."},
{"id":"TKP-3943","q":"Konten media sosial resmi yang dibuat dengan bantuan AI hendak dipublikasikan. Langkah paling tepat adalah ....","opts":[{"t":"Memverifikasi fakta dan bahasa konten sebelum publikasi oleh penanggung jawab","s":5},{"t":"Membaca ulang sebelum dipublikasikan","s":4},{"t":"Langsung mempublikasikan","s":3},{"t":"Mempublikasikan tanpa dibaca","s":2},{"t":"Mengaku konten buatan manual","s":1}],"ex":"Konten resmi berdampak publik; verifikasi manusia wajib sebelum tayang."},
{"id":"TKP-3944","q":"Aplikasi AI dipakai menyusun draf anggaran dan menemukan potensi penghematan. Sikap paling tepat adalah ....","opts":[{"t":"Memanfaatkan temuan sebagai bahan kajian, keputusan tetap lewat pembahasan manusia","s":5},{"t":"Mengkaji temuan AI itu","s":4},{"t":"Langsung memotong anggaran","s":3},{"t":"Mengabaikan temuan AI","s":2},{"t":"Menolak memakai AI untuk anggaran","s":1}],"ex":"Temuan AI adalah bahan kajian; keputusan anggaran tetap lewat pembahasan manusia."},
{"id":"TKP-3945","q":"Anda sadar chatbot AI di internet mengingat percakapan dan bisa membocorkan yang pernah diinput. Sikap paling tepat adalah ....","opts":[{"t":"Tidak lagi memasukkan data pribadi atau rahasia ke chatbot mana pun","s":5},{"t":"Menghapus riwayat percakapan","s":4},{"t":"Tetap memasukkan data seperti biasa","s":3},{"t":"Memasukkan data palsu untuk mengecoh","s":2},{"t":"Mengabaikan risiko itu","s":1}],"ex":"AI dapat menyimpan input; jangan pernah memasukkan data pribadi atau rahasia."},
{"id":"TKP-3946","q":"Dinas mengadakan pelatihan literasi AI digital untuk pegawai. Sikap paling tepat adalah ....","opts":[{"t":"Mengikuti aktif dan membagikan pengetahuan ke rekan","s":5},{"t":"Mengikuti pelatihan itu","s":4},{"t":"Ikut sekadar absen","s":3},{"t":"Menolak ikut","s":2},{"t":"Mengejek pelatihan itu","s":1}],"ex":"Literasi AI meningkatkan pemanfaatan yang aman dan bertanggung jawab."},
{"id":"TKP-3947","q":"Aplikasi AI dipakai untuk skrining awal berkas lamaran pegawai kontrak. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan kriteria transparan, ada audit bias, dan keputusan akhir oleh manusia","s":5},{"t":"Mendukung dengan pengawasan","s":4},{"t":"Menyerahkan sepenuhnya ke AI","s":3},{"t":"Menolak memakai AI","s":2},{"t":"Memanfaatkan untuk meloloskan kenalan","s":1}],"ex":"Skrining AI wajib transparan dan diaudit agar adil; manusia memegang keputusan akhir."},
{"id":"TKP-3948","q":"Aplikasi AI memprediksi potensi banjir di wilayah Anda minggu depan. Tindakan paling tepat adalah ....","opts":[{"t":"Meneruskan ke BPBD dan ahli untuk ditindaklanjuti sesuai prosedur kebencanaan","s":5},{"t":"Menyampaikan ke atasan","s":4},{"t":"Mengumumkan ke warga apa adanya","s":3},{"t":"Mengabaikan prediksi AI","s":2},{"t":"Menyebarkan sebagai kepastian","s":1}],"ex":"Prediksi AI adalah bahan kajian ahli, bukan pengumuman resmi; salurkan ke BPBD."},
{"id":"TKP-3949","q":"Rekan mengusulkan panduan etika aplikasi AI: kapan boleh, kapan dilarang. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan ikut merumuskan panduan yang praktis","s":5},{"t":"Mendukung usulan panduan","s":4},{"t":"Netral karena belum butuh","s":3},{"t":"Menolak karena ribet","s":2},{"t":"Mengabaikan usulan","s":1}],"ex":"Panduan etika AI memberi kepastian bagi pegawai dalam memanfaatkannya."},
{"id":"TKP-3950","q":"Warga bertanya apakah layanannya yang digital diproses manusia atau AI. Sikap paling tepat adalah ....","opts":[{"t":"Menjawab jujur tentang peran AI sebagai pembantu dan menjamin akuntabilitas manusia","s":5},{"t":"Menjawab jujur","s":4},{"t":"Menghindari pertanyaan itu","s":3},{"t":"Berbohong demi citra","s":2},{"t":"Menyalahkan AI bila ada keluhan","s":1}],"ex":"Transparansi peran AI membangun kepercayaan; akuntabilitas tetap pada manusia."},
{"id":"TKP-3951","q":"Di WhatsApp beredar hasil hitung cepat yang mengklaim pasangan calon tertentu menang telak, padahal pemungutan suara baru selesai. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menyebarkan, menunggu hasil resmi KPU, dan mengimbau rekan tidak ikut menyebar","s":5},{"t":"Menunggu hasil resmi KPU","s":4},{"t":"Menyimpan gambarnya untuk arsip","s":3},{"t":"Meneruskan dengan catatan belum resmi","s":2},{"t":"Ikut menyebarkan karena datanya rinci","s":1}],"ex":"Hitung cepat bukan hasil resmi; rujukan kemenangan hanya dari KPU."},
{"id":"TKP-3952","q":"Beredar di media sosial foto surat suara tercoblos yang diklaim dari TPS di daerah Anda. Foto itu ternyata dari pemilu lima tahun lalu. Tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan foto itu peristiwa lama, merujuk ke kanal resmi, dan tidak menyebarkannya","s":5},{"t":"Tidak ikut menyebarkan","s":4},{"t":"Meneruskan agar pengawas bertindak","s":3},{"t":"Mengunggah dengan tuntutan","s":2},{"t":"Menyebarkan sebagai bukti kecurangan","s":1}],"ex":"Foto lama yang diklaim baru adalah hoaks; verifikasi waktu dan sumber sebelum bereaksi."},
{"id":"TKP-3953","q":"Rekan ASN terang-terangan menyukai dan membagikan kampanye pasangan calon di media sosial. Saran paling tepat adalah ....","opts":[{"t":"Mengingatkan tentang netralitas ASN dan risiko sanksi, menyarankan menghapus unggahan","s":5},{"t":"Mengingatkan rekan tentang netralitas","s":4},{"t":"Membiarkan karena hak pribadi","s":3},{"t":"Ikut menyukai unggahannya","s":2},{"t":"Ikut berkampanye di media sosial","s":1}],"ex":"ASN wajib netral; kampanye di medsos melanggar netralitas dan berisiko sanksi."},
{"id":"TKP-3954","q":"Grup WhatsApp dinas dipakai untuk menggalang dukungan salah satu pasangan calon. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur, meminta berhenti, dan melaporkan bila berlanjut karena melanggar netralitas","s":5},{"t":"Mengingatkan agar grup steril dari kampanye","s":4},{"t":"Keluar dari grup diam-diam","s":3},{"t":"Ikut mendukung paslon favorit","s":2},{"t":"Membiarkan karena ramai","s":1}],"ex":"Fasilitas dinas dan grup kerja dilarang untuk kampanye; tegur dan laporkan."},
{"id":"TKP-3955","q":"Foto antrean panjang TPS beredar di internet dan diklaim sebagai bukti kecurangan terstruktur. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menyimpulkan sendiri, merujuk ke pengawas pemilu dan kanal resmi","s":5},{"t":"Menunggu klarifikasi resmi","s":4},{"t":"Meneruskan agar viral","s":3},{"t":"Mengomentari sebagai kecurangan","s":2},{"t":"Menyebarkan dengan narasi tuduhan","s":1}],"ex":"Dugaan kecurangan dilaporkan ke pengawas pemilu dengan bukti, bukan disebar sebagai tuduhan."},
{"id":"TKP-3956","q":"Beredar pesan berantai digital bahwa pemilih boleh mencoblos diwakilkan keluarga. Tetangga bertanya kebenarannya. Jawaban paling tepat adalah ....","opts":[{"t":"Menjelaskan pencoblosan tidak bisa diwakilkan sesuai aturan dan merujuk ke KPU","s":5},{"t":"Menjelaskan itu tidak benar","s":4},{"t":"Menyarankan bertanya ke RT","s":3},{"t":"Membiarkan tetangga percaya","s":2},{"t":"Membenarkan pesan itu","s":1}],"ex":"Hak pilih bersifat langsung dan tidak dapat diwakilkan; luruskan hoaks dengan aturan resmi."},
{"id":"TKP-3957","q":"Seseorang menawarkan uang via transfer digital agar Anda memilih pasangan calon tertentu. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak tegas dan melaporkan ke pengawas pemilu","s":5},{"t":"Menolak tawaran itu","s":4},{"t":"Menerima tetapi tetap pilih bebas","s":3},{"t":"Meminta tambah nominalnya","s":2},{"t":"Menerima dan memilih sesuai bayaran","s":1}],"ex":"Politik uang adalah pidana pemilu; tolak dan laporkan ke pengawas."},
{"id":"TKP-3958","q":"Anda mengetahui dari media sosial rekan ASN diam-diam menjadi tim sukses pasangan calon. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan tentang larangan dan risiko sanksi, menyarankan mundur","s":5},{"t":"Mengingatkan rekan tentang netralitas","s":4},{"t":"Mendiamkan karena urusan pribadi","s":3},{"t":"Ikut membantu timsesnya","s":2},{"t":"Merahasiakan dan mendukung","s":1}],"ex":"ASN dilarang menjadi tim sukses; ingatkan risiko sanksi dan sarankan mundur."},
{"id":"TKP-3959","q":"Video yang beredar di internet dan diklaim sebagai bukti kecurangan di TPS ternyata hasil potongan dan editan. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menyebarkan, menunjukkan versi utuhnya bila ada, dan merujuk ke pengawas","s":5},{"t":"Tidak ikut menyebarkan","s":4},{"t":"Meneruskan dengan tanda tanya","s":3},{"t":"Mengunggah dengan kecaman","s":2},{"t":"Menyebarkan sebagai bukti","s":1}],"ex":"Video potongan menyesatkan; bukti dugaan pelanggaran diserahkan ke pengawas pemilu."},
{"id":"TKP-3960","q":"Beredar di WhatsApp jadwal pemungutan suara yang berbeda dari pengumuman resmi. Warga bingung. Tindakan paling tepat adalah ....","opts":[{"t":"Merujuk warga ke jadwal resmi KPU dan mengimbau tidak menyebar jadwal palsu","s":5},{"t":"Menunjukkan jadwal resmi KPU","s":4},{"t":"Membiarkan warga memilih info sendiri","s":3},{"t":"Meneruskan jadwal yang beredar","s":2},{"t":"Membuat jadwal versi sendiri","s":1}],"ex":"Jadwal pemilu hanya dari KPU; jadwal palsu bisa menggagalkan hak pilih warga."},
{"id":"TKP-3961","q":"Beredar aplikasi cek daftar pemilih tetap yang meminta data lengkap dan izin akses kontak. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak mengunduh, mengecek DPT lewat situs resmi KPU, dan melaporkan aplikasi mencurigakan","s":5},{"t":"Mengecek DPT lewat situs resmi KPU","s":4},{"t":"Mengunduh karena butuh cepat","s":3},{"t":"Meneruskan aplikasi ke warga","s":2},{"t":"Mengunduh dan memberi semua izin","s":1}],"ex":"Aplikasi DPT palsu mencuri data; cek DPT hanya lewat kanal resmi KPU."},
{"id":"TKP-3962","q":"Survei elektabilitas via aplikasi pesan instan menunjukkan hasil yang janggal dan meminta donasi via aplikasi. Sikap paling tepat adalah ....","opts":[{"t":"Mengabaikan survei tak jelas metodologinya dan tidak mentransfer donasi","s":5},{"t":"Mengabaikan survei itu","s":4},{"t":"Mengisi survei sekadar iseng","s":3},{"t":"Meneruskan ke grup","s":2},{"t":"Mengisi dan berdonasi","s":1}],"ex":"Survei tanpa metodologi jelas tak bisa dipercaya; donasi via pesan instan rawan penipuan."},
{"id":"TKP-3963","q":"Grup WhatsApp warga memanas karena pendukung pasangan calon saling menghina. Anda anggota grup. Tindakan paling tepat adalah ....","opts":[{"t":"Mengimbau tenang, tidak ikut menghina, dan mengingatkan fokus pada informasi resmi","s":5},{"t":"Tidak ikut memanas-manasi","s":4},{"t":"Keluar dari grup","s":3},{"t":"Ikut membela jagoan Anda","s":2},{"t":"Ikut menghina kubu lawan","s":1}],"ex":"ASN meredam polarisasi dengan imbauan tenang dan rujukan informasi resmi."},
{"id":"TKP-3964","q":"Rekan ASN berfoto memakai atribut pasangan calon dan mengunggahnya ke media sosial. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan menghapus unggahan karena melanggar netralitas ASN","s":5},{"t":"Mengingatkan tentang aturan netralitas","s":4},{"t":"Membiarkan karena di luar jam kerja","s":3},{"t":"Ikut berfoto serupa","s":2},{"t":"Memberi selamat di kolom komentar","s":1}],"ex":"Atribut kampanye di medsos ASN melanggar netralitas meski di luar jam kerja."},
{"id":"TKP-3965","q":"Beredar kabar hoaks salah satu calon meninggal dunia menjelang pemungutan suara. Tindakan paling tepat adalah ....","opts":[{"t":"Mengecek ke sumber resmi dan tim calon, tidak menyebarkan sebelum terkonfirmasi","s":5},{"t":"Menunggu kabar resmi","s":4},{"t":"Meneruskan dengan ucapan duka","s":3},{"t":"Mengunggah kabar duka","s":2},{"t":"Menyebarkan kabar itu","s":1}],"ex":"Kabar kematian calon rawan hoaks; konfirmasi ke sumber resmi sebelum bereaksi."},
{"id":"TKP-3966","q":"Beredar QRIS digital donasi kampanye yang ternyata mengarah ke rekening pribadi tak dikenal. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak berdonasi, melaporkan dugaan penipuan, dan mengimbau warga waspada","s":5},{"t":"Tidak ikut berdonasi","s":4},{"t":"Berdonasi kecil untuk coba-coba","s":3},{"t":"Meneruskan ke grup","s":2},{"t":"Berdonasi karena mendukung","s":1}],"ex":"Donasi kampanye resmi lewat rekening terdaftar; QRIS asing patut diduga penipuan."},
{"id":"TKP-3967","q":"Warga menerima ancaman via WhatsApp agar tidak datang ke TPS. Ia melapor ke Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menenangkan warga, menyarankan melapor ke pengawas dan aparat, serta menegaskan hak pilihnya dilindungi","s":5},{"t":"Menyarankan melapor ke aparat","s":4},{"t":"Menyarankan warga tidak usah datang","s":3},{"t":"Mengabaikan laporan warga","s":2},{"t":"Ikut menakuti warga","s":1}],"ex":"Intimidasi pemilih adalah pidana; lindungi hak pilih warga dan laporkan pelaku."},
{"id":"TKP-3968","q":"Konten digital buatan AI menyerang pribadi pasangan calon beredar masif. Tindakan paling tepat adalah ....","opts":[{"t":"Tidak menyebarkan dan melaporkan konten manipulatif ke platform","s":5},{"t":"Tidak ikut menyebarkan","s":4},{"t":"Meneruskan karena menarik","s":3},{"t":"Menambah narasi serangan","s":2},{"t":"Ikut memproduksi konten serupa","s":1}],"ex":"Black campaign AI merusak demokrasi; jangan sebarkan dan laporkan kontennya."},
{"id":"TKP-3969","q":"Hasil rekap manual di TPS berbeda dengan yang tampil di aplikasi rekap digital. Sikap paling tepat adalah ....","opts":[{"t":"Mengikuti prosedur: rekap berjenjang resmi yang sah, laporkan perbedaan ke pengawas","s":5},{"t":"Melaporkan perbedaan ke pengawas","s":4},{"t":"Mempercayai aplikasi sepenuhnya","s":3},{"t":"Menyebarkan perbedaan itu","s":2},{"t":"Mengubah rekap manual agar cocok","s":1}],"ex":"Perbedaan rekap diselesaikan lewat prosedur berjenjang resmi, bukan opini viral."},
{"id":"TKP-3970","q":"Seorang ASN melakukan siaran langsung di media sosial mendukung pasangan calon. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan itu pelanggaran netralitas berat dan menyarankan menghentikan serta menghapus","s":5},{"t":"Mengingatkan tentang netralitas","s":4},{"t":"Menonton siarannya","s":3},{"t":"Ikut berkomentar mendukung","s":2},{"t":"Ikut siaran mendukung juga","s":1}],"ex":"Siaran dukungan paslon oleh ASN adalah pelanggaran netralitas yang nyata."},
{"id":"TKP-3971","q":"Beredar info hoaks TPS tutup pukul 10 pagi padahal resmi sampai pukul 13. Warga panik. Tindakan paling tepat adalah ....","opts":[{"t":"Meluruskan dengan jadwal resmi KPU dan mengimbau datang sesuai ketentuan","s":5},{"t":"Menunjukkan jadwal resmi","s":4},{"t":"Membiarkan warga percaya info itu","s":3},{"t":"Meneruskan info yang beredar","s":2},{"t":"Ikut panik","s":1}],"ex":"Hoaks jadwal bisa menghilangkan hak pilih; luruskan dengan jadwal resmi KPU."},
{"id":"TKP-3972","q":"Ajakan golput disertai hoaks bahwa suara pasti dicurangi beredar di kalangan pemilih muda. Sikap paling tepat adalah ....","opts":[{"t":"Mengedukasi tentang mekanisme pengamanan suara dan mengajak menggunakan hak pilih","s":5},{"t":"Mengajak tetap memilih","s":4},{"t":"Membiarkan pilihan masing-masing","s":3},{"t":"Ikut golput","s":2},{"t":"Menyebarkan ajakan golput","s":1}],"ex":"Hak pilih dilindungi mekanisme berlapis; edukasi melawan apatisme berbasis hoaks."},
{"id":"TKP-3973","q":"Data pemilih dari aplikasi diduga bocor dan disalahgunakan untuk kampanye. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan dugaan kebocoran ke penyelenggara dan aparat sesuai aturan perlindungan data","s":5},{"t":"Melaporkan ke atasan","s":4},{"t":"Mendiamkan karena rumit","s":3},{"t":"Memanfaatkan data untuk jagoan Anda","s":2},{"t":"Menyebarkan data itu","s":1}],"ex":"Data pemilih wajib dilindungi; kebocoran dilaporkan dan diproses sesuai aturan."},
{"id":"TKP-3974","q":"Usai pemungutan suara, beredar di media sosial klaim kemenangan sepihak sebelum rekap resmi selesai. Tindakan paling tepat adalah ....","opts":[{"t":"Menunggu rekap resmi berjenjang dan tidak ikut menyebar klaim sepihak","s":5},{"t":"Menunggu hasil resmi","s":4},{"t":"Merayakan klaim itu","s":3},{"t":"Menyebarkan klaim kemenangan","s":2},{"t":"Menolak hasil resmi nanti","s":1}],"ex":"Klaim sepihak memicu konflik; hasil sah hanya dari rekap resmi berjenjang."},
{"id":"TKP-3975","q":"Menjelang pemilu, pimpinan mengingatkan seluruh ASN menjaga netralitas di ruang digital. Sikap paling tepat adalah ....","opts":[{"t":"Berkomitmen penuh: tidak kampanye, tidak menyebar hoaks, dan saling mengingatkan","s":5},{"t":"Menjaga netralitas diri sendiri","s":4},{"t":"Netral di kantor, bebas di medsos pribadi","s":3},{"t":"Mendukung diam-diam","s":2},{"t":"Mengabaikan imbauan","s":1}],"ex":"Netralitas ASN berlaku di ruang digital; komitmen dan saling mengingatkan menjaganya."},
{"id":"TKP-3976","q":"Seorang ASN kerap memamerkan gaya hidup mewah di media sosial hingga jadi sorotan publik. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan tentang kepatutan dan risiko pemeriksaan harta, menyarankan menahan diri","s":5},{"t":"Mengingatkan agar lebih bijak","s":4},{"t":"Membiarkan karena hak pribadi","s":3},{"t":"Ikut memuji gaya hidupnya","s":2},{"t":"Ikut memamerkan juga","s":1}],"ex":"Flexing pejabat merusak kepercayaan publik dan memicu pemeriksaan; ASN wajib hidup patut."},
{"id":"TKP-3977","q":"Rekan melakukan siaran langsung media sosial saat jam dinas dari ruang kerjanya. Saran paling tepat adalah ....","opts":[{"t":"Mengingatkan itu melanggar disiplin jam kerja dan citra instansi","s":5},{"t":"Menyarankan berhenti siaran","s":4},{"t":"Membiarkan karena penontonnya banyak","s":3},{"t":"Ikut tampil di siarannya","s":2},{"t":"Ikut siaran di jam kerja juga","s":1}],"ex":"Siaran pribadi di jam dinas melanggar disiplin dan merendahkan marwah instansi."},
{"id":"TKP-3978","q":"ASN mengomentari kebijakan pemerintah dengan nada menghina di media sosial. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan kritik boleh lewat saluran resmi dengan bahasa santun, bukan hinaan publik","s":5},{"t":"Menyarankan menghapus komentar","s":4},{"t":"Membiarkan karena kebebasan berpendapat","s":3},{"t":"Ikut menghina","s":2},{"t":"Menyebarkan komentarnya","s":1}],"ex":"ASN boleh berpendapat lewat saluran resmi secara santun; hinaan publik melanggar etik."},
{"id":"TKP-3979","q":"Rekan mengunggah foto dokumen dinas berstempel ke status media sosialnya. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta segera menghapus dan melaporkan potensi pelanggaran keamanan informasi","s":5},{"t":"Meminta rekan menghapus unggahan","s":4},{"t":"Membiarkan karena sudah terlanjur","s":3},{"t":"Ikut menyimpan fotonya","s":2},{"t":"Ikut mengunggah dokumen lain","s":1}],"ex":"Dokumen dinas di medsos adalah pelanggaran keamanan informasi; hapus dan laporkan."},
{"id":"TKP-3980","q":"Pengunjung berswafoto di ruang server dan mengunggahnya ke media sosial. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta menghapus unggahan dan memperketat akses area terbatas","s":5},{"t":"Menegur pengunjung itu","s":4},{"t":"Membiarkan karena lucu","s":3},{"t":"Ikut berfoto di sana","s":2},{"t":"Mengunggah ulang fotonya","s":1}],"ex":"Area terbatas tak boleh diekspos; unggahan dihapus dan akses diperketat."},
{"id":"TKP-3981","q":"Rekan mencurahkan kekesalan soal atasan di media sosial hingga viral. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan menghapus dan menyalurkan keluhan lewat mekanisme resmi kepegawaian","s":5},{"t":"Menyarankan menghapus curhatan","s":4},{"t":"Membiarkan karena butuh pelampiasan","s":3},{"t":"Ikut berkomentar mendukung","s":2},{"t":"Ikut curhat serupa","s":1}],"ex":"Keluhan kedinasan disalurkan lewat mekanisme resmi, bukan viral di medsos."},
{"id":"TKP-3982","q":"Petugas mengunggah foto warga yang dilayani ke media sosial tanpa izin untuk konten. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta menghapus, meminta maaf ke warga, dan mengingatkan tentang persetujuan dan privasi","s":5},{"t":"Meminta menghapus foto itu","s":4},{"t":"Membiarkan karena niatnya baik","s":3},{"t":"Ikut membagikan kontennya","s":2},{"t":"Membuat konten serupa","s":1}],"ex":"Foto warga butuh izin; unggah tanpa persetujuan melanggar privasi."},
{"id":"TKP-3983","q":"Seorang ASN diduga menjadi pendengung berbayar isu politik di media sosial. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan itu melanggar netralitas dan etik, menyarankan berhenti","s":5},{"t":"Mengingatkan tentang netralitas","s":4},{"t":"Membiarkan karena sampingan","s":3},{"t":"Ikut menjadi pendengung","s":2},{"t":"Mempromosikan jasanya","s":1}],"ex":"ASN menjadi buzzer politik melanggar netralitas dan merusak kepercayaan publik."},
{"id":"TKP-3984","q":"Rekan memakai akun anonim untuk menghujat pihak lain di media sosial. Saran paling tepat adalah ....","opts":[{"t":"Mengingatkan anonimitas tak menghapus tanggung jawab hukum dan etik ASN","s":5},{"t":"Menyarankan berhenti menghujat","s":4},{"t":"Membiarkan karena anonim","s":3},{"t":"Ikut menghujat pakai akun anonim","s":2},{"t":"Membocorkan identitasnya","s":1}],"ex":"Akun anonim bukan tameng; jejak digital bisa dilacak dan ASN terikat etik."},
{"id":"TKP-3985","q":"Anda ingin mengunggah dokumentasi kegiatan dinas ke media sosial pribadi. Langkah paling tepat adalah ....","opts":[{"t":"Memastikan izin humas, tidak ada data sensitif, lalu mengunggah dengan narasi positif","s":5},{"t":"Meminta izin humas dulu","s":4},{"t":"Langsung mengunggah","s":3},{"t":"Mengunggah tanpa izin","s":2},{"t":"Mengunggah plus data internal","s":1}],"ex":"Dokumentasi dinas di medsos pribadi butuh izin humas dan bebas data sensitif."},
{"id":"TKP-3986","q":"Seorang ASN menerima tawaran endorse produk di media sosial pribadinya. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan tidak benturan dengan tugas, tidak memakai atribut dinas, dan mematuhi aturan","s":5},{"t":"Menerima dengan hati-hati","s":4},{"t":"Menolak semua tawaran","s":3},{"t":"Menerima sambil pakai seragam dinas","s":2},{"t":"Menerima tanpa pertimbangan","s":1}],"ex":"Endorse boleh selama tak memakai atribut dinas dan tak benturan dengan tugas."},
{"id":"TKP-3987","q":"Tantangan berbahaya viral di media sosial dan beberapa remaja jadi korban. Anak tetangga ingin ikut. Tindakan paling tepat adalah ....","opts":[{"t":"Mengedukasi orang tua dan anak tentang bahayanya serta melaporkan konten berbahaya","s":5},{"t":"Melarang anak itu ikut","s":4},{"t":"Membiarkan karena tren","s":3},{"t":"Ikut mencoba tantangannya","s":2},{"t":"Menyebarkan tantangannya","s":1}],"ex":"Tantangan berbahaya dilawan dengan edukasi dan pelaporan konten."},
{"id":"TKP-3988","q":"Rekan membagikan informasi rapat internal yang belum dipublikasikan ke media sosial. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta menghapus dan melaporkan pelanggaran disiplin informasi","s":5},{"t":"Meminta rekan menghapus","s":4},{"t":"Membiarkan karena sudah tersebar","s":3},{"t":"Ikut membagikan","s":2},{"t":"Menambahi bocoran lain","s":1}],"ex":"Informasi internal yang belum resmi dilarang disebar; hapus dan laporkan."},
{"id":"TKP-3989","q":"Akun ASN membalas keluhan warga di media sosial dengan kata-kata kasar. Sikap paling tepat adalah ....","opts":[{"t":"Mengingatkan menjaga bahasa pelayanan dan menyarankan meminta maaf serta mengoreksi","s":5},{"t":"Menyarankan meminta maaf","s":4},{"t":"Membiarkan karena warga yang mulai","s":3},{"t":"Ikut membalas kasar","s":2},{"t":"Menghapus akun saja","s":1}],"ex":"ASN wajib santun ke publik di ruang digital; kekasaran dikoreksi dan dimaafkan."},
{"id":"TKP-3990","q":"Anda melihat peluang memakai media sosial untuk edukasi layanan ke warga. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan konten edukasi resmi lewat akun dinas dengan bahasa mudah dipahami","s":5},{"t":"Membuat konten edukasi pribadi","s":4},{"t":"Membiarkan peluang itu","s":3},{"t":"Memakai untuk konten pribadi","s":2},{"t":"Mengabaikan media sosial","s":1}],"ex":"Medsos adalah kanal edukasi publik yang efektif bila dikelola resmi dan komunikatif."},
{"id":"TKP-3991","q":"Rekan kerap mengunggah foto anaknya ke media sosial dengan seragam sekolah dan lokasi yang jelas. Saran paling tepat adalah ....","opts":[{"t":"Mengingatkan risiko keamanan anak dari unggahan detail pribadi","s":5},{"t":"Menyarankan membatasi unggahan anak","s":4},{"t":"Membiarkan karena hak orang tua","s":3},{"t":"Ikut mengunggah anak Anda","s":2},{"t":"Menyebarkan foto anaknya","s":1}],"ex":"Detail anak di medsos berisiko keamanan; batasi informasi pribadi yang diunggah."},
{"id":"TKP-3992","q":"Akun media sosial resmi dinas dipakai admin untuk urusan pribadinya. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan penyalahgunaan akun resmi dan meminta pengelolaan sesuai prosedur","s":5},{"t":"Menegur admin itu","s":4},{"t":"Membiarkan karena sepele","s":3},{"t":"Ikut memakai akun itu","s":2},{"t":"Mengambil alih akunnya","s":1}],"ex":"Akun resmi adalah aset institusi; penyalahgunaan dilaporkan dan ditertibkan."},
{"id":"TKP-3993","q":"Anda hampir membagikan ulang kabar gembira di media sosial, lalu sadar belum memverifikasinya. Tindakan paling tepat adalah ....","opts":[{"t":"Menahan diri, memverifikasi dulu ke sumber tepercaya sebelum membagikan","s":5},{"t":"Tidak jadi membagikan","s":4},{"t":"Membagikan dengan catatan","s":3},{"t":"Membagikan saja","s":2},{"t":"Membagikan ke semua grup","s":1}],"ex":"Saring sebelum sharing: verifikasi dulu meski kabarnya menggembirakan."},
{"id":"TKP-3994","q":"Foto berseragam dinas Anda dipakai akun penipu di media sosial untuk meyakinkan korban. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan akun penipu, mengumumkan Anda tidak terkait, dan mengimbau waspada","s":5},{"t":"Melaporkan akun itu","s":4},{"t":"Menghapus semua foto seragam","s":3},{"t":"Membiarkan karena bukan salah Anda","s":2},{"t":"Menghubungi penipu","s":1}],"ex":"Identitas dicatut untuk penipuan harus segera dilaporkan dan diklarifikasi publik."},
{"id":"TKP-3995","q":"Akun mengatasnamakan instansi mengadakan giveaway di media sosial dan meminta biaya pendaftaran. Tindakan paling tepat adalah ....","opts":[{"t":"Mengumumkan itu penipuan lewat kanal resmi dan melaporkan akunnya","s":5},{"t":"Melaporkan akun penipu","s":4},{"t":"Mengabaikan","s":3},{"t":"Ikut mendaftar","s":2},{"t":"Meneruskan ke teman","s":1}],"ex":"Giveaway resmi tak memungut biaya; klarifikasi resmi melindungi warga."},
{"id":"TKP-3996","q":"Rekan ASN terlibat debat kusir panas di kolom komentar media sosial hingga membawa nama instansi. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan berhenti berdebat dan menjaga marwah instansi","s":5},{"t":"Menyarankan tidak melayani","s":4},{"t":"Ikut membela rekan","s":3},{"t":"Ikut menyerang lawan debat","s":2},{"t":"Menyebarkan debatnya","s":1}],"ex":"Debat kusir merendahkan marwah ASN; berhenti dan alihkan ke diskusi sehat."},
{"id":"TKP-3997","q":"Rekan selalu menandai lokasi real-time saat dinas luar di media sosial. Saran paling tepat adalah ....","opts":[{"t":"Mengingatkan risiko keamanan dan menyarankan menunda unggahan lokasi","s":5},{"t":"Menyarankan tidak menandai lokasi","s":4},{"t":"Membiarkan karena keren","s":3},{"t":"Ikut menandai lokasi","s":2},{"t":"Menyebarkan lokasinya","s":1}],"ex":"Lokasi real-time aparat berisiko keamanan; tunda unggahan sampai kegiatan selesai."},
{"id":"TKP-3998","q":"Anda tidak setuju kebijakan baru dan ingin mengkritiknya di media sosial. Langkah paling tepat adalah ....","opts":[{"t":"Menyampaikan kritik lewat mekanisme resmi internal dengan bahasa konstruktif","s":5},{"t":"Menyampaikan lewat atasan","s":4},{"t":"Mengunggah kritik pedas","s":3},{"t":"Menghasut rekan menolak","s":2},{"t":"Membocorkan dokumen kebijakan","s":1}],"ex":"Kritik ASN disalurkan lewat mekanisme resmi secara konstruktif, bukan viral."},
{"id":"TKP-3999","q":"Prinsip saring sebelum sharing hendak Anda terapkan dalam bermedia sosial. Wujud paling tepat adalah ....","opts":[{"t":"Memverifikasi kebenaran, mempertimbangkan dampak, lalu memutuskan membagikan atau tidak","s":5},{"t":"Memverifikasi sebelum membagikan","s":4},{"t":"Membagikan yang terlihat baik","s":3},{"t":"Membagikan semua yang viral","s":2},{"t":"Tidak pernah membagikan apa pun","s":1}],"ex":"Saring sebelum sharing: cek kebenaran dan timbang dampak sebelum membagikan."},
{"id":"TKP-4000","q":"Unit mengadakan pembinaan etik bermedia sosial bagi ASN. Sikap paling tepat adalah ....","opts":[{"t":"Mengikuti serius dan menerapkan dalam aktivitas digital sehari-hari","s":5},{"t":"Mengikuti pembinaan itu","s":4},{"t":"Ikut sekadar formalitas","s":3},{"t":"Menolak ikut","s":2},{"t":"Mengejek kegiatan itu","s":1}],"ex":"Etik digital adalah kompetensi ASN modern; ikuti serius dan terapkan."},
{"id":"TKP-4001","q":"Petugas loket lupa keluar dari akun aplikasi layanan di komputer umum. Anda melihatnya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengeluarkannya segera dan mengingatkan petugas tentang risiko akun tertinggal","s":5},{"t":"Mengeluarkan akun itu","s":4},{"t":"Membiarkan karena bukan akun Anda","s":3},{"t":"Memakai akun itu untuk iseng","s":2},{"t":"Menyebarkan bahwa akunnya terbuka","s":1}],"ex":"Akun tertinggal di komputer umum rawan disalahgunakan; keluarkan dan ingatkan pemiliknya."},
{"id":"TKP-4002","q":"Formulir digital layanan meminta data yang tidak relevan seperti hobi dan nama gadis ibu. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan penghapusan kolom tak relevan sesuai prinsip minimisasi data","s":5},{"t":"Mengosongkan kolom tak relevan","s":4},{"t":"Mengisi seadanya","s":3},{"t":"Mengisi lengkap apa adanya","s":2},{"t":"Menyebarkan formulir itu","s":1}],"ex":"Data pribadi hanya dikumpulkan seperlunya; kolom berlebihan wajib dievaluasi."},
{"id":"TKP-4003","q":"Seorang warga meminta datanya dihapus dari aplikasi layanan karena sudah tak dipakai. Tindakan paling tepat adalah ....","opts":[{"t":"Memproses permintaan hapus sesuai prosedur dan mengonfirmasi penyelesaiannya","s":5},{"t":"Meneruskan permintaan ke pengelola data","s":4},{"t":"Menyuruh warga menghapus aplikasinya","s":3},{"t":"Menolak karena data sudah masuk","s":2},{"t":"Mengabaikan permintaan warga","s":1}],"ex":"Subjek data berhak meminta penghapusan; layani sesuai prosedur yang berlaku."},
{"id":"TKP-4004","q":"Instansi menunjuk petugas pelindungan data pribadi untuk mengawasi kepatuhan. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dan berkoordinasi aktif dalam setiap isu data pribadi","s":5},{"t":"Mendukung penunjukan itu","s":4},{"t":"Netral karena bukan tugas Anda","s":3},{"t":"Menolak diawasi","s":2},{"t":"Mengabaikan perannya","s":1}],"ex":"Petugas pelindungan data adalah garda kepatuhan; dukung dan koordinasikan."},
{"id":"TKP-4005","q":"Warga menandatangani persetujuan pemrosesan data pribadi di aplikasi layanan tanpa membaca isinya. Sikap paling tepat adalah ....","opts":[{"t":"Menjelaskan isi persetujuan dengan bahasa sederhana sebelum ia menandatangani","s":5},{"t":"Menyarankan membaca dulu","s":4},{"t":"Membiarkan menandatangani","s":3},{"t":"Mendesak segera tanda tangan","s":2},{"t":"Mengabaikan","s":1}],"ex":"Persetujuan sah lahir dari pemahaman; jelaskan dengan bahasa sederhana."},
{"id":"TKP-4006","q":"Aplikasi layanan anak meminta foto dan data lengkap anak. Sikap paling tepat sebagai pengelola adalah ....","opts":[{"t":"Memastikan ada persetujuan orang tua dan perlindungan khusus data anak","s":5},{"t":"Membatasi data yang diminta","s":4},{"t":"Membiarkan seperti aplikasi dewasa","s":3},{"t":"Menambah data yang diminta","s":2},{"t":"Menjual data ke pengiklan","s":1}],"ex":"Data anak mendapat perlindungan khusus; wajib ada persetujuan orang tua."},
{"id":"TKP-4007","q":"Terjadi kebocoran data pribadi di sistem dan aturan mewajibkan pemberitahuan cepat. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan insiden segera lewat prosedur agar pemberitahuan ke otoritas dan subjek data tepat waktu","s":5},{"t":"Melaporkan ke atasan segera","s":4},{"t":"Menunggu perkembangan dulu","s":3},{"t":"Menyembunyikan insiden","s":2},{"t":"Menyebarkan ke media sosial","s":1}],"ex":"Keterlambatan pemberitahuan kebocoran memperberat sanksi; laporkan segera lewat prosedur."},
{"id":"TKP-4008","q":"Instansi memakai vendor untuk mengolah data warga di aplikasinya. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan ada perjanjian tertulis yang mengikat vendor menjaga kerahasiaan data","s":5},{"t":"Meminta vendor menjaga data","s":4},{"t":"Percaya penuh ke vendor","s":3},{"t":"Membiarkan vendor mengatur sendiri","s":2},{"t":"Menyerahkan semua data tanpa kontrak","s":1}],"ex":"Vendor pengolah data wajib terikat perjanjian kerahasiaan dan keamanan."},
{"id":"TKP-4009","q":"Basis data digital warga belum terenkripsi dan bisa dibaca siapa pun yang mengakses server. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan enkripsi segera ke unit TI sebagai pengaman dasar","s":5},{"t":"Melaporkan ke unit TI","s":4},{"t":"Membiarkan karena belum bocor","s":3},{"t":"Menyebarkan akses server","s":2},{"t":"Mengabaikan temuan","s":1}],"ex":"Enkripsi adalah pengaman dasar data; usulkan segera sebelum terjadi kebocoran."},
{"id":"TKP-4010","q":"Arsip digital warga yang masa retensinya habis masih tersimpan menumpuk. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan pemusnahan sesuai jadwal retensi dan prosedur yang sah","s":5},{"t":"Menghapus yang sudah kedaluwarsa","s":4},{"t":"Menyimpan selamanya untuk jaga-jaga","s":3},{"t":"Menjual arsip lama","s":2},{"t":"Membiarkan menumpuk","s":1}],"ex":"Data yang melewati masa retensi wajib dimusnahkan prosedural, bukan disimpan selamanya."},
{"id":"TKP-4011","q":"Rekan menyebarkan kabar penyakit serius yang diderita pegawai lain di grup WhatsApp. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan data kesehatan bersifat rahasia dan meminta pesan dihapus","s":5},{"t":"Menegur rekan itu","s":4},{"t":"Ikut prihatin di grup","s":3},{"t":"Meneruskan kabar itu","s":2},{"t":"Menambahi detail penyakitnya","s":1}],"ex":"Data kesehatan adalah data pribadi sensitif; dilarang disebar tanpa izin."},
{"id":"TKP-4012","q":"Survei kepuasan digital meminta NIK responden padahal tak relevan. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan survei anonim tanpa NIK demi melindungi responden","s":5},{"t":"Mengosongkan kolom NIK","s":4},{"t":"Mengisi NIK apa adanya","s":3},{"t":"Mengisi NIK palsu","s":2},{"t":"Menyebarkan survei itu","s":1}],"ex":"Survei tak butuh NIK; anonimitas melindungi responden dan meningkatkan kejujuran."},
{"id":"TKP-4013","q":"Data pribadi warga hendak dikirim ke pihak ketiga di luar negeri untuk kerja sama. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan ada dasar hukum dan pelindungan memadai sebelum transfer dilakukan","s":5},{"t":"Meminta persetujuan pimpinan dulu","s":4},{"t":"Langsung mengirim","s":3},{"t":"Mengirim sebagian dulu","s":2},{"t":"Menjual data itu","s":1}],"ex":"Transfer data lintas negara wajib memenuhi syarat pelindungan hukum."},
{"id":"TKP-4014","q":"Semua pegawai bisa mengakses seluruh data warga di aplikasi tanpa batasan peran. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan pembatasan akses berbasis peran sesuai kebutuhan tugas","s":5},{"t":"Melaporkan ke unit TI","s":4},{"t":"Membiarkan karena memudahkan","s":3},{"t":"Memanfaatkan akses luas itu","s":2},{"t":"Menyebarkan cara aksesnya","s":1}],"ex":"Akses data dibatasi sesuai peran; akses tanpa batas rawan penyalahgunaan."},
{"id":"TKP-4015","q":"Ada usulan audit berkala siapa mengakses data pribadi warga di sistem. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung audit sebagai pencegah penyalahgunaan dan siap diperiksa","s":5},{"t":"Mendukung usulan audit","s":4},{"t":"Netral karena merepotkan","s":3},{"t":"Menolak diaudit","s":2},{"t":"Menghapus jejak akses","s":1}],"ex":"Audit akses menekan penyalahgunaan data; dukung dan patuhi."},
{"id":"TKP-4016","q":"Warga meminta salinan seluruh data pribadinya yang tersimpan di instansi. Tindakan paling tepat adalah ....","opts":[{"t":"Memverifikasi identitasnya lalu memberikan salinan sesuai prosedur","s":5},{"t":"Meneruskan permintaan ke pengelola data","s":4},{"t":"Menolak dengan alasan rumit","s":3},{"t":"Memberi tanpa verifikasi","s":2},{"t":"Mengabaikan permintaan","s":1}],"ex":"Hak akses data milik subjek data; layani setelah verifikasi identitas."},
{"id":"TKP-4017","q":"Keluarga meminta data almarhum yang tersimpan di aplikasi layanan. Sikap paling tepat adalah ....","opts":[{"t":"Memproses sesuai aturan tentang data subjek yang meninggal dan ahli waris","s":5},{"t":"Meneruskan ke pimpinan","s":4},{"t":"Langsung memberikan semua","s":3},{"t":"Menolak mentah-mentah","s":2},{"t":"Mengabaikan","s":1}],"ex":"Data almarhum diatur tersendiri; proses lewat aturan dan verifikasi ahli waris."},
{"id":"TKP-4018","q":"Data pribadi warga hendak dipakai untuk riset dengan identitas disamarkan. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung dengan memastikan penyamaran benar-benar melindungi identitas","s":5},{"t":"Mendukung riset itu","s":4},{"t":"Menolak semua riset","s":3},{"t":"Memberi data asli agar akurat","s":2},{"t":"Menjual data riset","s":1}],"ex":"Riset boleh memakai data tersamar selama identitas benar-benar terlindungi."},
{"id":"TKP-4019","q":"Email berisi data pribadi puluhan warga salah kirim ke alamat luar. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta penerima menghapus, menarik kembali bila mungkin, dan melaporkan insiden","s":5},{"t":"Meminta penerima menghapus email","s":4},{"t":"Mendiamkan karena sudah terkirim","s":3},{"t":"Menyalahkan sistem email","s":2},{"t":"Mengirim lagi ke alamat benar","s":1}],"ex":"Salah kirim data wajib ditindaklanjuti: minta hapus, tarik, dan laporkan insiden."},
{"id":"TKP-4020","q":"Warga meminta data yang pernah ia berikan dihapus permanen dari arsip digital. Tindakan paling tepat adalah ....","opts":[{"t":"Memverifikasi identitas dan menghapus permanen sesuai prosedur serta mengonfirmasi","s":5},{"t":"Menghapus dari aplikasi","s":4},{"t":"Menolak karena arsip","s":3},{"t":"Menghapus sebagian","s":2},{"t":"Mengabaikan","s":1}],"ex":"Permintaan penghapusan permanen dilayani prosedural setelah verifikasi identitas."},
{"id":"TKP-4021","q":"Pengunjung memotret dokumen arsip di ruang layanan dengan ponselnya untuk disebar di internet. Tindakan paling tepat adalah ....","opts":[{"t":"Melarang pemotretan arsip dan menjelaskan aturan perlindungan dokumen","s":5},{"t":"Menegur pengunjung itu","s":4},{"t":"Membiarkan karena dokumen umum","s":3},{"t":"Ikut memotretkan","s":2},{"t":"Mengabaikan","s":1}],"ex":"Arsip layanan dilarang difoto untuk mencegah penyalahgunaan data."},
{"id":"TKP-4022","q":"Warga mengklik setuju pada syarat aplikasi tanpa membaca. Sebagai petugas edukasi, tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan pentingnya membaca poin data pribadi sebelum menyetujui","s":5},{"t":"Menyarankan membaca dulu","s":4},{"t":"Membiarkan","s":3},{"t":"Ikut mengklik setuju","s":2},{"t":"Menyalahkan warga","s":1}],"ex":"Edukasi membaca syarat melindungi warga dari persetujuan yang merugikan."},
{"id":"TKP-4023","q":"Absensi digital memakai data sidik jari yang tersimpan di server. Sikap paling tepat adalah ....","opts":[{"t":"Memastikan data biometrik disimpan aman dan hanya untuk absensi","s":5},{"t":"Mendukung absensi biometrik","s":4},{"t":"Menolak mentah-mentah","s":3},{"t":"Meminta salinan datanya","s":2},{"t":"Menyebarkan data biometrik","s":1}],"ex":"Data biometrik tak bisa diganti bila bocor; pastikan tersimpan aman dan terbatas."},
{"id":"TKP-4024","q":"Ada evaluasi kepatuhan pelindungan data pribadi di unit Anda. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung evaluasi dan menindaklanjuti temuannya dengan perbaikan nyata","s":5},{"t":"Mendukung evaluasi itu","s":4},{"t":"Netral karena merepotkan","s":3},{"t":"Menolak dievaluasi","s":2},{"t":"Memalsukan dokumen kepatuhan","s":1}],"ex":"Evaluasi kepatuhan adalah cermin perbaikan; dukung dan tindaklanjuti."},
{"id":"TKP-4025","q":"Rekan menyimpan daftar data pribadi warga di spreadsheet tanpa kata sandi di komputer bersama. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta segera diamankan dengan kata sandi dan dipindah ke sistem resmi","s":5},{"t":"Menegur rekan itu","s":4},{"t":"Membiarkan karena praktis","s":3},{"t":"Ikut menyalin datanya","s":2},{"t":"Menyebarkan spreadsheet itu","s":1}],"ex":"Data pribadi di berkas tanpa pengaman rawan bocor; amankan dan pindahkan ke sistem resmi."},
{"id":"TKP-4026","q":"Ponsel dinas yang terhubung internet terus menunda pembaruan sistem operasi karena dianggap mengganggu. Sikap paling tepat adalah ....","opts":[{"t":"Segera memasang pembaruan karena menutup celah keamanan perangkat","s":5},{"t":"Memasang saat senggang","s":4},{"t":"Menunda terus","s":3},{"t":"Menonaktifkan pembaruan","s":2},{"t":"Mengabaikan selamanya","s":1}],"ex":"Pembaruan OS menambal celah keamanan; penundaan membuat perangkat mudah diserang."},
{"id":"TKP-4027","q":"Akun-akun digital dinas Anda belum memakai verifikasi dua langkah. Tindakan paling tepat adalah ....","opts":[{"t":"Mengaktifkan verifikasi dua langkah di semua akun penting segera","s":5},{"t":"Mengaktifkan di akun utama","s":4},{"t":"Menunda karena ribet","s":3},{"t":"Hanya mengandalkan kata sandi","s":2},{"t":"Menonaktifkan semua pengaman","s":1}],"ex":"Verifikasi dua langkah menggagalkan pembobolan meski kata sandi bocor."},
{"id":"TKP-4028","q":"Rekan mencatat semua kata sandi akun digital di kertas yang ditempel di monitor. Saran paling tepat adalah ....","opts":[{"t":"Menyarankan memakai pengelola kata sandi dan memusnahkan catatan kertas","s":5},{"t":"Menyarankan menyimpan di tempat aman","s":4},{"t":"Membiarkan karena praktis","s":3},{"t":"Ikut mencatat di kertas","s":2},{"t":"Memotret catatan itu","s":1}],"ex":"Kata sandi di kertas mudah dicuri; pengelola kata sandi lebih aman."},
{"id":"TKP-4029","q":"Ponsel dinas yang menyimpan data digital belum dienkripsi sehingga datanya bisa dibaca bila perangkat dibongkar. Tindakan paling tepat adalah ....","opts":[{"t":"Mengaktifkan enkripsi perangkat sesuai panduan TI","s":5},{"t":"Meminta bantuan TI","s":4},{"t":"Membiarkan karena rumit","s":3},{"t":"Menonaktifkan kunci layar","s":2},{"t":"Mengabaikan","s":1}],"ex":"Enkripsi melindungi data bila perangkat hilang atau dibongkar."},
{"id":"TKP-4030","q":"Rekan memakai ponsel pribadi untuk mengakses aplikasi dinas tanpa aturan jelas. Sikap paling tepat adalah ....","opts":[{"t":"Mengusulkan aturan perangkat pribadi: pemisahan profil kerja dan pengamanan minimal","s":5},{"t":"Menyarankan berhati-hati","s":4},{"t":"Membiarkan","s":3},{"t":"Ikut memakai ponsel pribadi","s":2},{"t":"Menyebarkan data dinas","s":1}],"ex":"Perangkat pribadi untuk kerja butuh aturan: profil terpisah dan standar pengamanan."},
{"id":"TKP-4031","q":"Layar ponsel dinas yang berisi aplikasi kerja tidak terkunci otomatis sehingga terbuka bila ditinggal. Tindakan paling tepat adalah ....","opts":[{"t":"Mengaktifkan kunci layar otomatis singkat dan biometrik","s":5},{"t":"Mengaktifkan kunci layar","s":4},{"t":"Membiarkan terbuka","s":3},{"t":"Menitipkan ke rekan","s":2},{"t":"Menonaktifkan kunci","s":1}],"ex":"Kunci otomatis mencegah akses tak sah saat perangkat ditinggal."},
{"id":"TKP-4032","q":"Bluetooth dan koneksi internet ponsel dinas selalu aktif di tempat umum. Tindakan paling tepat adalah ....","opts":[{"t":"Mematikan saat tak dipakai untuk mencegah penyusupan nirkabel","s":5},{"t":"Mematikan bluetooth saja","s":4},{"t":"Membiarkan aktif","s":3},{"t":"Mengaktifkan semua koneksi","s":2},{"t":"Mengabaikan","s":1}],"ex":"Koneksi nirkabel yang selalu aktif membuka celah penyusupan; matikan bila tak dipakai."},
{"id":"TKP-4033","q":"Aplikasi senter meminta akses ke kontak dan lokasi. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak izin tak relevan atau menghapus aplikasi dan memakai yang tepercaya","s":5},{"t":"Menolak izinnya","s":4},{"t":"Memberi semua izin","s":3},{"t":"Memberi sebagian","s":2},{"t":"Mengabaikan","s":1}],"ex":"Izin harus sesuai fungsi aplikasi; tolak yang berlebihan."},
{"id":"TKP-4034","q":"Rekan mengunduh aplikasi dari situs luar, bukan toko aplikasi resmi, agar gratis. Saran paling tepat adalah ....","opts":[{"t":"Melarang karena rawan malware dan menyarankan versi resmi","s":5},{"t":"Menyarankan menghapus","s":4},{"t":"Membiarkan","s":3},{"t":"Meminta salinannya","s":2},{"t":"Ikut mengunduh","s":1}],"ex":"Aplikasi luar toko resmi kerap disusupi malware; pakai sumber resmi."},
{"id":"TKP-4035","q":"Foto dokumen dinas otomatis tercadangkan via internet ke cloud pribadi Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Mematikan pencadangan otomatis untuk folder dinas dan memindahkan ke penyimpanan resmi","s":5},{"t":"Mematikan pencadangan otomatis","s":4},{"t":"Membiarkan","s":3},{"t":"Membagikan cloud pribadi","s":2},{"t":"Mengunggah lebih banyak","s":1}],"ex":"Dokumen dinas dilarang di cloud pribadi; gunakan penyimpanan resmi instansi."},
{"id":"TKP-4036","q":"Isi pesan WhatsApp tampil di layar terkunci ponsel dinas. Tindakan paling tepat adalah ....","opts":[{"t":"Menyembunyikan isi notifikasi di layar kunci demi privasi","s":5},{"t":"Mengurangi notifikasi","s":4},{"t":"Membiarkan","s":3},{"t":"Memperbesar tampilannya","s":2},{"t":"Mengabaikan","s":1}],"ex":"Notifikasi di layar kunci bisa dibaca orang lain; sembunyikan isinya."},
{"id":"TKP-4037","q":"Hotspot internet pribadi Anda aktif tanpa kata sandi saat dinas luar. Tindakan paling tepat adalah ....","opts":[{"t":"Memberi kata sandi kuat atau mematikannya bila tak dipakai","s":5},{"t":"Memberi kata sandi","s":4},{"t":"Membiarkan terbuka","s":3},{"t":"Membagikan ke semua orang","s":2},{"t":"Mengabaikan","s":1}],"ex":"Hotspot terbuka bisa disusupi; amankan dengan kata sandi kuat."},
{"id":"TKP-4038","q":"Anda menerima notifikasi transaksi digital nirsentuh yang tidak Anda lakukan. Tindakan paling tepat adalah ....","opts":[{"t":"Segera memblokir kartu lewat aplikasi bank dan melaporkan transaksi asing","s":5},{"t":"Melaporkan ke bank","s":4},{"t":"Menunggu tagihan","s":3},{"t":"Mengabaikan","s":2},{"t":"Mencoba transaksi lagi","s":1}],"ex":"Transaksi asing wajib segera diblokir dan dilaporkan ke bank."},
{"id":"TKP-4039","q":"Rekan meneruskan semua email dinas ke email pribadinya agar mudah dibaca via aplikasi di rumah. Saran paling tepat adalah ....","opts":[{"t":"Melarang karena melanggar keamanan informasi dan menyarankan akses resmi","s":5},{"t":"Menyarankan berhenti","s":4},{"t":"Membiarkan","s":3},{"t":"Ikut meneruskan","s":2},{"t":"Menyebarkan emailnya","s":1}],"ex":"Email dinas dilarang diteruskan ke pribadi; gunakan akses resmi yang aman."},
{"id":"TKP-4040","q":"Kalender digital pribadi Anda tersinkron dengan jadwal dinas yang bersifat internal. Tindakan paling tepat adalah ....","opts":[{"t":"Memisahkan kalender dinas dan pribadi agar jadwal internal tak tersebar","s":5},{"t":"Membatasi berbagi kalender","s":4},{"t":"Membiarkan tersinkron","s":3},{"t":"Membagikan ke publik","s":2},{"t":"Mengabaikan","s":1}],"ex":"Jadwal internal di kalender pribadi rawan bocor; pisahkan keduanya."},
{"id":"TKP-4041","q":"Asisten suara digital di ponsel dinas aktif dan merekam percakapan sekitar. Tindakan paling tepat adalah ....","opts":[{"t":"Menonaktifkan asisten suara di perangkat dinas","s":5},{"t":"Membatasi izin mikrofon","s":4},{"t":"Membiarkan aktif","s":3},{"t":"Memakai untuk mencatat rapat","s":2},{"t":"Mengabaikan","s":1}],"ex":"Asisten suara yang selalu mendengar berisiko merekam pembicaraan sensitif."},
{"id":"TKP-4042","q":"Kamera laptop dinas yang terhubung internet tidak tertutup dan bisa aktif tanpa disadari. Tindakan paling tepat adalah ....","opts":[{"t":"Menutup kamera fisik dan memeriksa izin aplikasi yang memakai kamera","s":5},{"t":"Menutup kamera","s":4},{"t":"Membiarkan","s":3},{"t":"Menghadapkan ke dinding","s":2},{"t":"Mengabaikan","s":1}],"ex":"Kamera yang terbuka bisa disalahgunakan; tutup fisik dan kelola izinnya."},
{"id":"TKP-4043","q":"Seseorang tak dikenal meminta dikirimi berkas digital via berbagi nirkabel di tempat umum. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak dan memastikan fitur berbagi hanya untuk kontak tepercaya","s":5},{"t":"Menolak","s":4},{"t":"Menerima karena penasaran","s":3},{"t":"Mengirim balik","s":2},{"t":"Mengabaikan","s":1}],"ex":"Berbagi nirkabel ke asing berisiko malware; batasi hanya untuk kontak tepercaya."},
{"id":"TKP-4044","q":"Anda memindai kode untuk masuk aplikasi pesan di komputer umum kantor. Setelah selesai, tindakan paling tepat adalah ....","opts":[{"t":"Keluar dari semua sesi di perangkat itu dan periksa perangkat tertaut","s":5},{"t":"Keluar dari aplikasi","s":4},{"t":"Menutup browser saja","s":3},{"t":"Membiarkan tetap masuk","s":2},{"t":"Mengabaikan","s":1}],"ex":"Sesi di komputer umum wajib diakhiri total agar tak disalahgunakan."},
{"id":"TKP-4045","q":"Anda sadar sesi aplikasi pesan masih aktif di komputer yang sudah tidak dipakai. Tindakan paling tepat adalah ....","opts":[{"t":"Mengakhiri sesi dari jarak jauh lewat pengaturan perangkat tertaut","s":5},{"t":"Segera kembali untuk keluar","s":4},{"t":"Membiarkan","s":3},{"t":"Berharap tak ada yang pakai","s":2},{"t":"Mengabaikan","s":1}],"ex":"Sesi tertinggal bisa diakhiri jarak jauh; lakukan segera."},
{"id":"TKP-4046","q":"Aplikasi penting di ponsel dinas sudah tak didukung pembaruan pengembang. Tindakan paling tepat adalah ....","opts":[{"t":"Menghapus dan mengganti dengan aplikasi yang masih didukung","s":5},{"t":"Mencari pengganti","s":4},{"t":"Tetap memakai","s":3},{"t":"Mengunduh versi modifikasi","s":2},{"t":"Mengabaikan","s":1}],"ex":"Aplikasi usang tak ditambal keamanannya; ganti dengan yang didukung."},
{"id":"TKP-4047","q":"Izin lokasi di ponsel dinas selalu aktif untuk semua aplikasi. Tindakan paling tepat adalah ....","opts":[{"t":"Membatasi izin lokasi hanya saat aplikasi dipakai dan hanya untuk yang butuh","s":5},{"t":"Mematikan untuk sebagian","s":4},{"t":"Membiarkan","s":3},{"t":"Mengaktifkan semua","s":2},{"t":"Mengabaikan","s":1}],"ex":"Pelacakan lokasi berlebihan membahayakan privasi; batasi seperlunya."},
{"id":"TKP-4048","q":"Ponsel dinas yang menyimpan data digital hendak diservis karena rusak. Tindakan paling tepat sebelumnya adalah ....","opts":[{"t":"Mencadangkan data resmi, menghapus data sensitif, dan mengunci perangkat","s":5},{"t":"Menghapus data sensitif","s":4},{"t":"Langsung diservis","s":3},{"t":"Membiarkan apa adanya","s":2},{"t":"Menitipkan tanpa kunci","s":1}],"ex":"Perangkat diservis bisa diakses teknisi; amankan data sebelum diserahkan."},
{"id":"TKP-4049","q":"Ponsel dinas lama yang menyimpan data digital akan dilelang dan diganti baru. Tindakan paling tepat adalah ....","opts":[{"t":"Menghapus total ke setelan pabrik dan memastikan data tak bisa dipulihkan","s":5},{"t":"Menghapus manual","s":4},{"t":"Langsung dilelang","s":3},{"t":"Memberi ke rekan","s":2},{"t":"Membuang sembarangan","s":1}],"ex":"Perangkat dinas yang dipindahtangankan wajib dihapus total agar data tak bocor."},
{"id":"TKP-4050","q":"Unit mencanangkan gerakan higiene digital: perangkat aman, kata sandi kuat, waspada phishing. Sikap paling tepat adalah ....","opts":[{"t":"Mendukung penuh dan menerapkannya mulai dari perangkat sendiri","s":5},{"t":"Mendukung gerakan itu","s":4},{"t":"Netral karena ribet","s":3},{"t":"Menolak","s":2},{"t":"Mengejek gerakan itu","s":1}],"ex":"Higiene digital dimulai dari diri sendiri; dukung dan terapkan."}
];
